INSERT INTO cj_guide_base (id, topic, rules, scope, feishu_id) VALUES
(1, '从这里开始', '按这个顺序看：① 驾驶舱：一页看结论和质量。② 3.3 质量检查：先看哪些缺口在阻断结论。③ 1 研究：商业模式 → 证据账本 → 事实→判断映射。④ 2 估值：情景参数 → 年度假设 → 财务计算 → 估值结论；2.5、2.6 看假设变化的影响。⑤ 3 跟踪：跟踪任务和市场数据看什么变了，任何改动写入 3.4 变更日志。4 后台、5 归档日常无需打开。每张表默认打开“日常”视图，要看明细切到“全部字段”。', '全部公司', 'recvvElWrBUrCc'),
(2, '表格地图', '1 研究（为什么值得研究）：1.1 商业模式＝怎么赚钱、护城河需要什么证据；1.2 证据账本＝原文事实与来源；1.3 映射＝事实如何变成参数判断，以及反证和不改条件。
INSERT INTO cj_biz_model_base (id, proposition, company_code, earning_mechanism, moat_evidence, counter_view, financial_mapping, current_view, feishu_id) VALUES
(1, '水电量价', '600900.SH', '以售电量×不含税结算电价形成售电收入；发电量需扣厂用电和损耗，其他业务单列。', '流域开发权、优质坝址、梯级调度；用跨周期单位成本和回报验证。', '稀缺资产不等于自由提价权；政策和市场化交易可分享利润。', '电量→售电量→电价→收入', '可理解的长寿命生意；估值输入待核验', 'recvvElYu5TVy0'),
(2, '来水与正常盈利', '600900.SH', '按水文年、蓄水、水头、调度和装机可用率估计发电，不将丰水年永久化。', '至少5—10年、可比六站口径水电量；区分收购并表与自然增长。', '长期气候改变、连续枯水和弃水；单站入库流量不能代表全流域。', '近年电量调整，不自动改变终值增长', '短期波动与长期产能分离', 'recvvElYu5QDrH'),
(3, '折旧与更新', '600900.SH', '利润随会计折旧变化；资产更新仍消耗真实现金。', '按电站、资产类别、投运年份核验折旧表和大修更新。', '大坝寿命不等于机组寿命；折旧退坡时间表目前是旧假设。', '折旧→税前利润；现金加回→扣维护资本', '利润改善未必等额增加所有者收益', 'recvvElYu5reda'),
(4, '负债与分红', '600900.SH', '利息取决于平均带息负债和有效借款成本；偿债、投资和分红共用现金。', '债务到期表、利率、受限资金、母子公司分配和净借款。', '分红承诺受盈利、偿债和法律可分配能力约束。', '利息→净利；净偿债→FCFE；股息现金覆盖', '不能同时承诺高分红与无成本快速去杠杆', 'recvvElYu5cid6'),
(5, '再投资与治理', '600900.SH', '新项目价值来自增量资本回报超过资本成本，而非单纯扩大规模。', '项目预算、完工进度、投产电价、增量ROIC；关联交易公允性。', '抽蓄、扩能及收购可能低回报或超预算；不计收益时也不能漏支出。', '扩张资本→现金减少；投产后收入成本税费', '以每股长期现金回报衡量管理层', 'recvvElYu5x2Bj'),
(6, '投资收益与少数股东', '600900.SH', '权益法利润不是当期可支配现金；归母和合并口径需要桥接。', '被投资企业分红、少数股东利润及分红、母公司现金。', '用合并CFO估归母FCFE可能高估。', '剔除非现金权益收益，加入实际现金分红与归属调整', '待补现金桥接', 'recvvElYu5bCZz');
