(15, 'LEGACY-FORECAST', '600900.SH', '2026—2035', '旧模型假设', '原表模型预测2026—2035共10年数值与公式已快照；折旧和财务费用逐年下降属于假设。', 'https://b7okxcyuao.feishu.cn/base/PMnCb5BsGaME0ysW21uc7pHJnDb?table=tbl3AWSnfetyBe6F', '2026-09-01', '2026-09-19', '假设待验证', '不作为已披露事实；V2用于条件计算及敏感性。', NULL, 'recvvEm0i4tNWz'),
(16, 'RATE-LEGACY-20260831', '600900.SH', '2026-08-31', '旧参数字典迁移', '旧参数字典记录无风险利率1.69%（2026-08-31）、风险溢价3.5%；二者求和5.19%，按0.1个百分点四舍五入为基准折现率5.2%。', 'https://b7okxcyuao.feishu.cn/base/PMnCb5BsGaME0ysW21uc7pHJnDb?table=tblwC6gbfMfQjipH&record=recvtZ1gqKrxlm', '旧表未标注', '2026-09-25', '旧参数待核验', '仅复现旧模型的长期折现率选择；当期中债观察值只用于跟踪，不自动替换长期折现率。旧参数未按官方原件复核。', 'recvtZ1gqKrxlm;recvtZ1gqKtIu8;recvtZ1gqK0anB', 'recvwbTK56jufG');
INSERT INTO cj_fact_mapping_base (id, mapping_id, fact_layer, judgment, math_transmission, param_key, affected_years, change_threshold, no_change_condition, counter_evidence, judgment_status, feishu_id) VALUES
(1, 'MAP-Q', '观察到来水/发电数据后才录入数值', '短期偏枯可能下调年度电量，不必永久化', 'Δ收入=Δ售电量×不含税电价；经税、现金及折现传导', 'generation', '2026近端；结构变化才及远期', '公司季度电量或经回测的水文—发电关系；同口径累计比较', '只有单日、单站流量异常，或已包含在假设内', '水头、库容与调度可抵消流量影响', '研究规则；未新增事实', 'recvvEm23srzfZ'),
(2, 'MAP-P', '合同结算或报告披露电价', '政策和交易结构改变平均实现价格', 'Δ收入=售电量×Δ实现电价', 'tariff', '合同生效期及各情景', '确认含税/不含税、地区、结算量和生效日期', '只有政策标题或行业平均电价', '含税变动、售电结构、境外汇率及其他业务混合', '研究规则；未新增事实', 'recvvEm23sGRmN'),
(3, 'MAP-DA', '折旧政策及资产明细原件待核验', '旧模型折旧下降可能提升利润，但不等额增加现金', '净利+ΔD×(1-t)，加回折旧-ΔD；现金净效应约-ΔD×t，另计税务差异', 'depreciation', '2026—2035', '按资产类别折旧台账、税务及更新预算', '仅推测大坝寿命或设备账面折旧到期', '重新购置机组和大修支出上升；税务折旧不同', '研究规则；未新增事实', 'recvvEm23sbUpu'),
(4, 'MAP-DEBT', '债务到期、利率、净融资与付息分类', '降息/去杠杆可降利息但偿债消耗现金', '利息=平均债务×有效利率；FCFE另加净借款', 'interest;net_borrowing', '逐年；利率冲击独立于经营情景', '财报债务附注与现金融资勾稽', '只看到国债利率下降', '新项目加杠杆、浮息重定价延迟', '研究规则；未新增事实', 'recvvEm23sRaFv'),
(5, 'MAP-CAPEX', '维持性/扩张性资本项目及预算', '只认可增量回报超过资本成本的增长', 'FCFE扣全部资本开支；所有者收益扣维持资本；终值增长需再投资支持', 'maintenance_capex;growth_capex', '建设期现金流及投产后收益', '项目公告和支付进度，区分承诺额与当年现金支付', '只有规划装机，无预算与进度', '建设延期、超支、容量电价政策和关联交易', '研究规则；未新增事实', 'recvvEm23sbMTZ'),
(6, 'MAP-CASH', '归母净利与合并CFO口径不同', '需非现金、权益法分红、少数股东等桥接', '归母利润+归属折旧-非现金收益+投资现金分红-Δ营运资本-资本开支+净借款', 'noncash_adjustment;cash_investment;minority', '所有年度', '逐项现金桥接；未知值留空，不能默认0', '只算CFO减资本开支', '营运资本释放与一次性回款不可永久化', '研究规则；未新增事实', 'recvvEm23sYuxg'),
(7, 'MAP-R', '国债收益率观察值需日期与来源', '要求回报率由无风险参考、风险补偿与机会成本共同决定', 'r上升→现金折现下降；不改变经营现金流', 'discount_rate', '估值全期限', '记录名义人民币口径与期限，独立做利率压力', '单日波动不自动覆盖长期要求回报', '低利率未必长期持续，风险溢价不能机械固定', '研究规则；未新增事实', 'recvvEm23sa6rb'),
(8, 'MAP-TV', '终期盈利、资本更新与增长条件', '永续增长必须有留存与回报支撑', '终值=规范化下一年分配/(r-g)；r必须大于g', 'terminal_growth', '2036及以后', '更新资本、负债与分配可持续；同时报告终值占比', '仅以国债低利率或大坝寿命支持高终值', '资产寿命/气候/监管结构变化；终值占比高', '研究规则；未新增事实', 'recvvEm23sbZsu');
