INSERT INTO cj_change_log_base (id, change_id, time_text, target, old_value, new_value, reason, evidence_ref, verify_status, feishu_id) VALUES
(1, 'V2-INITIAL-20260919', '2026-09-19', '工作台结构与估值链', '10张原表+旧估值看板', '增加V2研究、证据、映射、输入、公式、决策、监控与质量层', '用户要求可复用价值投资数据库；保留旧模型对照，分离事实判断与现金口径', '本地快照20260919T153616；原表未覆盖', '78项工程检查通过；财务证据仍待核验', 'recvvEmrVCoYmT'),
(2, 'LOG-NEGATIVE-20260920', '2026-09-20', 'V2_11市场观察及三峡历史看板', '三条负流量观察混入有效看板', '原记录保留；质量有效=0，图表排除；备用采集拒收负数及非有限值', '入库流量出现-14200、-10000、-4900；未经来源核验，不擅自变更为正数', 'Z3791116 2026-08-27/09-07；K4903912 2026-08-31；原Wind响应留存', '隔离完成；原始水文事实待核验', 'recvvIF9RuJxF8'),
(3, 'LOG-CLOUD-20260920', '2026-09-20', 'V2云端自动化、市场观察与看板', '本机Wind采集+Codex定时；电脑离线不可执行', '9条飞书原生工作流：3采集、3入库、3异常自检；18:30/18:40/19:10；本机定时暂停', '满足电脑与Codex离线仍采集的要求；保留原始响应、日期、口径与去重轨迹', 'V2_14六次真实抓取；V2_11新增3条观测；V2_15三项正常自检记录', '三来源工程链路通过；三峡/向家坝入库流量与公告PDF仍待接通；正式模型假设未改', 'recvvIHUH4c22S'),
(4, 'V2-LINK-20260925', '2026-09-25', '年度假设、情景控制、估值链、市场观察与质量检查', '年度共同参数逐年重复、情景股本和估值年份重复、跟踪任务最新观察为固定文字', '基准输入加单年覆盖；无风险利率1.69%与风险溢价3.5%在表内相加并按0.1个百分点取整为5.2%；公式贯通财务引擎、估值与敏感性；市场观察回查原始采集并汇总到跟踪任务；现金桥接状态实时计算；历史折旧与财务费用缺项保留空白；质量检查及驾驶舱图实时勾稽', '减少重复录入并保留原始输入、证据与估值结果之间的可追溯关系', '2026-09-25线上快照与逐行数值对账；V2_04来源证据连接LEGACY-FORECAST', '三情景、30财务行、25敏感性、5沙盘改造前后数值一致；17条云端观察均匹配原始采集；历史完整5年合计未变、缺项7年由误示0改为空白；现金口径及旧利率来源仍待核验', 'recvwbT23Kp13y'),
(5, 'LOG-SIMPLIFY-20261021', '2026-10-21', '工作台目录、表名、默认视图、使用指南、驾驶舱文字', '根目录26张表平铺（V1十张与V2混放）；表名V2_00—V2_15编号与目录顺序不一致；默认视图显示全部字段（财务引擎44列）；使用指南12条；工作流名带V2前缀', '驾驶舱＋使用指南＋5个文件夹（1研究/2估值/3跟踪/4后台/5归档）；表名按阅读顺序编号1.1—4.2；每表默认“日常”视图只留关键列，另设“全部字段”视图；使用指南合并为9条并新增表格地图；工作流按①采集②入库③自检命名；Wind停更图表标注；V1十张表、旧估值看板和两份旧文档移入归档', '让人按“研究→估值→跟踪”的顺序理解框架；不改任何字段、公式、记录数值和工作流逻辑', '改前本地备份：表结构、全部记录、视图字段、看板配置、工作流定义；本地audit.py与monitor.py改为按表ID访问', 'audit.py 83项通过0失败；三情景条件DDM 14.24/26.19/36.65元与改前一致；工作流与看板引用随表ID自动更名', 'reczz28Q0XQjCZt1');
