(69, 'CJH-SX-LEVEL|2026/10/10 18:30', 'CJH-SX-LEVEL', 'http://www.cjh.com.cn/sqindex.html', '米', '2026-10-10T18:30:04.864+08:00', '完成（新增或已去重）', '{"status_code":200,"$startTime":1791628208875,"$endTime":1791628209305,"body":"<html lang=\"zh-CN\" xmlns=\"http://www.w3.org/1999/xhtml\">\r\n\r\n\t<head>\r\n\t\t<meta charset=\"utf-8\">\r\n\t\t<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\" />\r\n\t\t<title>水情信息</title>\r\n\t\t<meta name=\"viewport\" content=\"width=device-width, initial-scale=1,maximum-scale=1, user-scalable=no\">\r\n\t\t<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\r\n\t\t<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black\">\r\n\t\t<link rel=\"stylesheet\" href=\"assetscjsw/styles/reset.css\" />\r\n\t\t<link rel=\"stylesheet\" href=\"assetscjsw/styles/common.css\" />\r\n\t\t<link rel=\"stylesheet\" href=\"assetscjsw/styles/index.css\" />\r\n<style>\r\n.sssq tr{border-top: 1px solid #e7ecf1;}\r\n</style>\r\n\t</head>\r\n\r\n\t<body>\r\n<table class=''sssq'' width=\"100%\" cellspacing=\"1\" cellpadding=\"1\">\r\n\t\t\t<tbody id=\"sssqold\">\r\n\t\t\t</tbody>\r\n\t\t</table>\r\n<script type=\"text/javascript\" src=\"assetscjsw/plugin/jquery.min.js\"></script>\r\n\t\t<script type=\"text/javascript\">\r\n\t\t\tloadSQ();\r\n\t\t\t// 加载水情数据\r\n\t\t\tfunction loadSQ() {\r\n\t\t\t\tvar sssq = [{\"q\":\"10700\",\"rvnm\":\"长江干流\",\"stcd\":\"60105400\",\"stnm\":\"寸滩\",\"tm\":1791626400000,\"wptn\":\"6\",\"z\":\"173.770\"},{\"q\":\"1390\",\"rvnm\":\"乌江\",\"stcd\":\"60803000\",\"stnm\":\"武隆\",\"tm\":1791626400000,\"wptn\":\"5\",\"z\":\"175.060\"},{\"q\":\"10500\",\"rvnm\":\"长江干流\",\"stcd\":\"60107300\",\"stnm\":\"宜昌\",\"tm\":1791626400000,\"wptn\":\"5\",\"z\":\"41.270\"},{\"q\":\"10500\",\"rvnm\":\"长江干流\",\"stcd\":\"60108300\",\"stnm\":\"沙市\",\"tm\":1791626400000,\"wptn\":\"5\",\"z\":\"31.550\"},{\"rvnm\":\"长江干流\",\"stcd\":\"60111200\",\"stnm\":\"莲花塘\",\"tm\":1791626400000,\"wptn\":\"6\",\"z\":\"22.600\"},{\"q\":\"16200\",\"rvnm\":\"长江干流\",\"stcd\":\"60112200\",\"stnm\":\"汉口\",\"tm\":1791626400000,\"wptn\":\"6\",\"z\":\"16.650\"},{\"q\":\"16600\",\"rvnm\":\"长江干流\",\"stcd\":\"60113400\",\"stnm\":\"九江\",\"tm\":1791626400000,\"wptn\":\"4\",\"z\":\"11.030\"},{\"q\":\"19700\",\"rvnm\":\"长江干流\",\"stcd\":\"60115000\",\"stnm\":\"大通\",\"tm\":1791626400000,\"wptn\":\"4\",\"z\":\"6.870\"},{\"q\":\"4690\",\"rvnm\":\"洞庭湖湖口\",\"stcd\":\"61512000\",\"stnm\":\"七里山\",\"tm\":1791626400000,\"wptn\":\"4\",\"z\":\"22.630\"},{\"q\":\"3240\",\"rvnm\":\"鄱阳湖\",\"stcd\":\"62601600\",\"stnm\":\"湖口\",\"tm\":1791626400000,\"wptn\":\"6\",\"z\":\"10.270\"},{\"rvnm\":\"长江\",\"stcd\":\"60107000\",\"stnm\":\"茅坪(二)\",\"tm\":1791626400000,\"wptn\":\"4\",\"z\":\"172.920\"},{\"oq\":\"13200\",\"rvnm\":\"长江干流\",\"stcd\":\"60106980\",\"stnm\":\"三峡水库\",\"tm\":1791626400000,\"wptn\":\"4\",\"z\":\"172.920\"},{\"rvnm\":\"汉江\",\"stcd\":\"61802500\",\"stnm\":\"龙王庙\",\"tm\":1791626400000,\"wptn\":\"6\",\"z\":\"165.860\"},{\"oq\":\"760\",\"q\":\"345\",\"rvnm\":\"汉江\",\"stcd\":\"61802700\",\"stnm\":\"丹江口水库\",\"tm\":1791626400000,\"wptn\":\"6\",\"z\":\"165.860\"}];\r\n\t\t\t\t\r\n\t\t\t\tvar sqHtml = \"<tr><td class=''tb1''><b>站名</b></td><td class=''tb1''><b>时间</b></td><td class=''tb1''><b>水位</b>(m)</td><td class=''tb1'' style=''padding-bottom: 3px;''><b>流量</b>(m<sup>3</sup>/s)</td></tr>\";\r\n\t\t\t\tfor(var i = 0; i < sssq.length; i++) {\r\n\t\t\t\t\tvar sssqTmp = sssq[i]\r\n\t\t\t\t\tvar trClass=\"\";\r\n\t\t\t\t\tif(i%2==0){\r\n\t\t\t\t\t\ttrClass=\"tb0\";\r\n\t\t\t\t\t}else{\r\n\t\t\t\t\t\ttrClass=\"tb1\";\r\n\t\t\t\t\t}\r\n\t\t\t\t\tvar z = \"-\";\r\n\t\t\t\t\tvar q = \"-\";\r\n\t\t\t\t\tvar oq = \"-\";\r\n\t\t\t\t\tvar wptnColor = \"\";\r\n\t\t\t\t\tif(sssqTmp.z) {\r\n\t\t\t\t\t\tz = (sssqTmp.z * 1).toFixed(2);\r\n\t\t\t\t\t}\r\n\t\t\t\t\tif(sssqTmp.q > 0) {\r\n\t\t\t\t\t\tq = (sssqTmp.q * 1).toFixed(0);\r\n\t\t\t\t\t}\r\n\t\t\t\t\tif(sssqTmp.oq > 0) {\r\n\t\t\t\t\t\toq = (sssqTmp.oq * 1).toFixed(0);\r\n\t\t\t\t\t}\r\n\t\t\t\t\tif(sssqTmp.wptn == 4) {\r\n\t\t\t\t\t\t// 落\r\n\t\t\t\t\t\twptnColor = ''#009900'';\r\n\t\t\t\t\t} else if(sssqTmp.wptn == 5) {\r\n\t\t\t\t\t\t// 涨\r\n\t\t\t\t\t\twptnColor = ''#ff0000'';\r\n\t\t\t\t\t}\r\n\t\t\t\t\tvar ioqTd = ''<td class=\"''+trClass+''\">'' + q + ''</td>'';\r\n\t\t\t\t\tif(oq != ''-'') {\r\n\t\t\t\t\t\tioqTd = ''<td class=\"''+trClass+''\">'' + q + ''(入)<br/>'' + oq + ''(出)'' + ''</td>'';\r\n\t\t\t\t\t}\r\n\t\t\t\t\t\r\n\t\t\t\t\tsqHtml += ''<tr><td class=\"''+trClass+''\"><a href=\"#''+sssqTmp.stcd+''\" >'' + sssqTmp.stnm + ''</a></td><td class=\"''+trClass+''\">'' + getTime(sssqTmp.tm) + ''</td><td class=\"''+trClass+''\"><font color=\"'' + wptnColor + ''\">'' + z + ''</font></td>'' + ioqTd + ''</tr>'';\r\n\r\n//sqHtml += ''<tr><td class=\"''+trClass+''\"><a href=\"#\" >'' + sssqTmp.stnm + ''</a></td><td class=\"''+trClass+''\">'' + sssqTmp.tm + ''</td><td class=\"''+trClass+''\"><font color=\"'' + wptnColor + ''\">'' + z + ''</font></td>'' + ioqTd + ''</tr>'';\r\n\t\t\t\t}\r\n$(\"#sssqold\").html(sqHtml);\r\n\t\t\t}\r\n\r\n\t\t\tfunction getTime(ntime) {\r\nif(ntime==''-''){return ''-'';}\r\n\t\t\t\tvar now = new Date(ntime);\r\n\t\t\t\tvar year = now.getYear();\r\n\t\t\t\tvar month = now.getMonth() + 1;\r\n\t\t\t\tvar date = now.getDate();\r\n\t\t\t\tvar hour = now.getHours();\r\n\t\t\t\tvar minute = now.getMinutes();\r\n\t\t\t\tvar second = now.getSeconds();\r\n\t\t\t\treturn PrefixInteger(date, 2) + \"日 \" + PrefixInteger(hour, 2) + \"时\"+PrefixInteger(minute, 2) + \"分\";;\r\n\r\n\t\t\t}\r\n\t\t\tfunction PrefixInteger(num, n) {\r\n\t\t\t\treturn(Array(n).join(0) + num).slice(-n);\r\n\t\t\t}\r\n\r\nwindow.addEventListener(''message'',function(rs){\r\n    var pointdata=rs.data;\r\nif(pointdata==''refresh''){\r\n     window.location.reload();\r\n}else{\r\nconsole.log(pointdata);\r\n}\r\n})\r\n</script>\r\n\t</body>\r\n\r\n</html>\r\n","headers":{"X-Bd-Upstream-Id":"lf-lf02-bgp","Connection":"Keep-Alive","Content-Type":"text/html;charset=utf-8","Date":"Sat, 10 Oct 2026 10:30:21 GMT","Server":"nginx","Set-Cookie":"WJSESSIONID=5458D5F3C82851F459228A85ECFE9AE6; Path=/; HttpOnly","X-Bd-Remote-Connection-Info":"lf-lf02-bgp; bind=123.58.10.239; local=123.58.10.239:29534; remote=219.140.196.72:80"}}', 'reczz28LfvIwAkfc'),
(70, 'CHINABOND-CGB10Y|2026/10/11 18:30', 'CHINABOND-CGB10Y', 'https://yield.chinabond.com.cn/cbweb-pbc-web/pbc/more?locale=cn_zh', '%', '2026-10-11T18:30:01.603+08:00', '完成（重复观察未新增）', '{"$startTime":1791714605318,"$endTime":1791714606514,"body":"\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html>\r\n<head>\r\n\t<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\" />\r\n\t\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n <script type=\"text/javascript\" >\r\n        var ctx=\"/cbweb-pbc-web\";\r\n        var ctxStatics=\"/cbweb-pbc-web/statics\";\r\n </script>\r\n\r\n\r\n\r\n\t<meta http-equiv=\"Content-Type\" content=\"text/html;charset=utf-8\" />\n<meta http-equiv=\"Cache-Control\" content=\"no-store\" /><meta http-equiv=\"Pragma\" content=\"no-cache\" />\n<meta http-equiv=\"Expires\" content=\"0\" />\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\" />\n<script src=\"/cbweb-pbc-web/statics/js/jquery/jquery-1.9.1.min.js\" type=\"text/javascript\"></script>\n<script type=\"text/javascript\" src=\"/cbweb-pbc-web/statics/js/jquery-ztree/jquery.ztree.core-3.5.js\"></script>\n<script type=\"text/javascript\" src=\"/cbweb-pbc-web/statics/js/jquery-ztree/jquery.ztree.excheck-3.5.js\"></script>\n<script src=\"/cbweb-pbc-web/statics/My97DatePicker/WdatePicker.js\" type=\"text/javascript\"></script>\n\r\n<title>国债及其他债券收益率曲线</title>\r\n \r\n\r\n\t<link rel=\"stylesheet\" type=\"text/css\" href=\"/cbweb-pbc-web/statics/css/indexCn.css\" id=\"css\" />\r\n\r\n   \r\n<script src=\"/cbweb-pbc-web/statics/js/My97DatePicker/WdatePicker.js\"\r\n\ttype=\"text/javascript\"></script>\r\n\t\r\n<script src=\"/cbweb-pbc-web/statics/js/custom/statusCheck.js\"\r\n\ttype=\"text/javascript\"></script>\r\n\t\r\n<script src=\"/cbweb-pbc-web/statics/js/higchart/highstock_pbc.js\"\r\n\ttype=\"text/javascript\"></script>\r\n\t\r\n<script src=\"/cbweb-pbc-web/statics/js/higchart/colorArr.js\"\r\n\ttype=\"text/javascript\"></script>\r\n\r\n</head>\r\n<body>\r\n\t<div id=\"Container\">\r\n\t\t<div id=\"Header\">\r\n\t\t\t   <div id=\"title\"><!-- 国债及其他收益率曲线 -->国债及其他债券收益率曲线</div>\r\n\t           <div id=\"ytitle\">中央国债登记结算有限责任公司编制<!--  中央国债登记结算有限责任公司编制 --></div>\r\n\t\t</div>\r\n\t\t<div class=\"Clear\"></div>\r\n\t\t<div id=\"Content\">\r\n\t\t\t<div id=\"dateText\"><!-- 日期 -->日期:</div>\r\n\t\t\t<div id=\"datePop\">\r\n\t\t\t    \r\n\t\t        \r\n\t\t            <input name=\"gzr\" id=\"gzr\" type=\"text\" class=\"date\" value=\"2026-10-10\"\r\n\t\t\t\t\t\t\tonclick=\"WdatePicker({dateFmt:''yyyy-MM-dd'',isShowClear:false\r\n\t\t\t\t\t\t\t ,isShowToday:false,isShowOK:false,readOnly:true,lang:''zh-cn''});\" />\r\n\t\t        \r\n\t\t\t</div>\r\n\t\t\t<div id=\"searchBut\">\r\n\t\t\t    <input type=\"button\" value=\"查询\" onclick=\"query()\"/>\r\n\t\t\t\t<input type=\"button\" value=\"历史数据\" onclick=\"historyQuery()\"/>\r\n\t\t\t</div>\r\n\t\t</div>\r\n\t\t\r\n\t\t<div id = \"graph\" class=\"graph\" align=\"left\"></div>\r\n\t\t   \r\n\t\t<div id=\"gjqxData\">\r\n\t\t\t<table  border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\r\n\t\t\t\t <tr>\r\n\t\t\t\t \r\n\t\t\t\t    <th>2026-10-10(%)</th>\r\n\t\t\t\t\t<!--<th style=\"border-left:1px solid #000000\"> 隔夜 隔夜</th>-->\r\n\t\t\t\t    <th style=\"border-left:1px solid #000000\">3<!-- 月 -->月</th>\r\n\t\t\t\t    <th style=\"border-left:1px solid #000000\">6<!-- 月 -->月</th>\r\n\t\t\t\t    <th style=\"border-left:1px solid #000000\">1<!-- 年 -->年</th>\r\n\t\t\t\t    <th style=\"border-left:1px solid #000000\">3<!-- 年 -->年</th>\r\n\t\t\t\t    <th style=\"border-left:1px solid #000000\">5<!-- 年 -->年</th>\r\n\t\t\t\t    <th style=\"border-left:1px solid #000000\">7<!-- 年 -->年</th>\r\n\t\t\t\t    <th style=\"border-left:1px solid #000000\">10<!-- 年 -->年</th>\r\n\t\t\t\t    <th style=\"border-left:1px solid #000000\">30<!-- 年 -->年</th>\r\n\t\t\t\t</tr>\r\n\t\t\t\t\r\n\t\t\t\t    <tr>\r\n\t\t\t\t       <td style=\"width: 250px;text-align: left; line-height: 1\">中债国债收益率曲线</td>\r\n                      <!--  <td style=\"border-left:1px solid #000000\">0.9240 </td> -->\r\n                       <td style=\"border-left:1px solid #000000\">1.1680</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.1940</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.2147</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.2803</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.4069</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.5103</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.6849</td>\r\n                       <td style=\"border-left:1px solid #000000\">2.0870</td>\r\n\t\t\t\t    </tr>\r\n\t\t\t\t\r\n\t\t\t\t    <tr>\r\n\t\t\t\t       <td style=\"width: 250px;text-align: left; line-height: 1\">中债商业银行普通债收益率曲线(AAA)</td>\r\n                      <!--  <td style=\"border-left:1px solid #000000\">1.3141 </td> -->\r\n                       <td style=\"border-left:1px solid #000000\">1.4144</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.4399</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.4718</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.5518</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.5727</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.7050</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.8582</td>\r\n                       <td style=\"border-left:1px solid #000000\">2.2825</td>\r\n\t\t\t\t    </tr>\r\n\t\t\t\t\r\n\t\t\t\t    <tr>\r\n\t\t\t\t       <td style=\"width: 250px;text-align: left; line-height: 1\">中债中短期票据收益率曲线(AAA)</td>\r\n                      <!--  <td style=\"border-left:1px solid #000000\">1.4400 </td> -->\r\n                       <td style=\"border-left:1px solid #000000\">1.4458</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.4500</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.4994</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.6252</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.6874</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.8114</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.9600</td>\r\n                       <td style=\"border-left:1px solid #000000\"></td>\r\n\t\t\t\t    </tr>\r\n\t\t\t\t\r\n\t\t\t</table>\r\n\t\t</div>\r\n\t\t<div id=\"zhu\"> <!-- 注：表中三个月期限国债收益率是用于计算SDR利率的人民币代表性利率 -->注：&nbsp;表中三个月期限国债收益率是用于计算SDR利率的人民币代表性利率</div>\r\n\t\t<div id=\"font1\">\r\n\t\t\t\r\n\t\t\t\t<div style=\"font-weight:bold; text-align: center;\">\r\n\t\t               <!-- 国债及其他收益率曲线简介 -->国债及其他债券收益率曲线简介\r\n\t\t    \t</div>\r\n\t\t\t\r\n\t\t      <div>\r\n\t\t         &nbsp; &nbsp; <!-- 国债及其他收益率曲线是由中央国债登记结算有限责任公司(www.chinabond.com.cn)编制提供的一组反映在岸人民币债券市场到期收益率走势的图表。\r\n\t\t                            其中，国债收益率曲线样本包括记账式附息国债和记账式贴现国债；AAA级商业银行普通债曲线样本包括同业存单和商业银行债券；AAA级中短期票据曲线样本包括AAA级超短期融资券、短期融资券和中期票据 -->\r\n\t\t                            国债及其他债券收益率曲线是由中央国债登记结算有限责任公司(www.chinabond.com.cn)编制提供的一组反映在岸人民币债券市场到期收益率走势的图表。其中，国债收益率曲线样本包括记账式附息国债和记账式贴现国债；AAA级商业银行普通债收益率曲线样本包括同业存单和商业银行债券；AAA级中短期票据收益率曲线样本包括AAA级超短期融资券、短期融资券和中期票据。\r\n\t\t      </div>\r\n\t\t      <div>\r\n\t\t        &nbsp; &nbsp; <!-- 中债收益率曲线包括国债在内的各信用等级的到期、即期和远期收益曲线约1000余条，采用赫尔米特模型编制。曲线数据源包括银行间市场和交易所市场的做市商报价、\r\n\t\t                       货币经纪公司报价、成交价和结算价等。收益率曲线的样本点优先选取新发行且满足流动性要求的债券。中债收益率曲线每个工作日日终发布一次，发布时间为北京时间17:30 -->\r\n\t\t                           中债收益率曲线包括国债在内的各信用等级的到期、即期和远期收益曲线约1000余条，采用赫尔米特模型编制。曲线数据源包括银行间市场和交易所市场的做市商报价、货币经纪公司报价、成交价和结算价等。收益率曲线的样本点优先选取新发行且满足流动性要求的债券。中债收益率曲线每个工作日日终发布一次，发布时间为北京时间17:30。\r\n\t\t     </div>\r\n\t\t</div>\r\n\t</div>\r\n\t<input type=\"hidden\" id=\"locale\" value=\"cn_ZH\">\r\n</body>\r\n\r\n<script type=\"text/javascript\">\r\n\r\n    Highcharts.setOptions({\r\n        global: {\r\n            useUTC: false\r\n        },\r\n    });\r\n    var chart = null;\r\n    var xData=new Array();\r\n    var options = {\r\n        chart : {\r\n            exporting : {\r\n                enabled : true //用来设置是否显示‘打印’,''导出''等功能按钮，不设置时默认为显示\r\n            },\r\n            renderTo : ''graph'',\r\n            type: ''line'',\r\n            marginBottom : 90,\r\n            marginTop : 5,\r\n            marginLeft : 50,\r\n        },\r\n        title : {\r\n            text : ''''\r\n        },\r\n        xAxis : {\r\n            labels:{\r\n                style:{\r\n                    fontSize:''10px'',\r\n                    fontFamily: \"宋体\",\r\n                    color: \"#333333\",\r\n                }\r\n            },\r\n            crosshair: {\r\n                width: 1,\r\n                color: ''#CC0000''\r\n            },\r\n            categories:xData,\r\n            tickPositions: [0,10, 20,30, 50,70,110],\r\n            tickWidth : 1,\r\n            gridLineWidth : 1,\r\n            lineWidth : 1,\r\n            lineColor : ''black'',\r\n            showFirstLabel : true,\r\n            showLastLable : true,\r\n            tickLength : 0,\r\n        },\r\n\r\n        yAxis : [ {\r\n            labels : {\r\n                format : ''{value:.,0f}'',\r\n                padding : 50,\r\n                x : -10,\r\n                formatter : function(){\r\n                    return this.value.toFixed(2);//这里是两位小数，你要几位小数就改成几\r\n                },\r\n                style:{\r\n                    fontWeight:\"normal\",\r\n                    fontSize: \"10px\",\r\n                    fontFamily: \"宋体\",\r\n                    color: \"#333333\",\r\n                }\r\n            },\r\n            title : {\r\n                text : ''(%)'',\r\n                align: ''high'',\r\n                offset: 5,\r\n                rotation:0,\r\n                y: 85,\r\n                x: -30,\r\n                style:{\r\n                    fontWeight:\"normal\",\r\n                    fontSize: \"10px\",\r\n                    fontFamily: \"宋体\",\r\n                    color: \"#333333\",\r\n                }\r\n            },\r\n            tickPixelInterval: 50,\r\n            allowDecimals : true,//是否显示小数\r\n            showFirstLabel : true,\r\n            tickPosition : ''outside'',\r\n            tickLength : 3,\r\n            opposite : false,//设置y轴在对面显示\r\n            lineWidth : 1,//设置y轴的线宽\r\n            tickWidth : 1,\r\n            tickColor : ''black'',\r\n            lineColor : ''black'',\r\n        } ],\r\n\r\n        legend : {\r\n            enabled : true,\r\n            align: ''left'',\r\n            layout: ''vertical'',\r\n            floating: true,\r\n            itemMarginTop: 3,\r\n            x: 45,\r\n            y: 10,\r\n            itemStyle: {\r\n                fontWeight:\"normal\",\r\n                fontSize: \"12px\",\r\n                fontFamily: \"宋体\",\r\n                color: \"#333333\",\r\n                cursor: \"default\",\r\n            },\r\n        },\r\n        credits : {\r\n            enabled : false //去掉higcharts.com\r\n        },\r\n        tooltip : {\r\n            shared : false,\r\n            split : true,\r\n            animation : false,\r\n            shape : ''square'',\r\n            crosshairs : {\r\n                width : 1,\r\n                color : ''red''\r\n            },\r\n            distance : 3,//距离某个点的距离\r\n            useHTML : true,\r\n            borderWidth : 1,\r\n            headerFormat : ''<small style=\"background-color:#DC143C\">{point.key}</small><table border=\"5\">'',\r\n            pointFormat : ''<tr><td style=\"text-align: right,color:{point.color}\">{point.y:.4f}%</td></tr>'',\r\n            footerFormat : ''</table>'',\r\n        },\r\n        plotOptions : {\r\n            series: {\r\n                animation:false,\r\n                states:{\r\n                    hover:{\r\n                        lineWidthPlus: 0\r\n                    },\r\n                },\r\n                marker:{\r\n                    symbol:''circle'',\r\n                    enabled:true,\r\n                    radius:0.1\r\n                },\r\n                connectNulls:true,//连接空点\r\n            },\r\n        },\r\n        series : []\r\n    }\r\n    function query(){\r\n        queryGjqxInfo();\r\n\r\n        var workTime=document.getElementById(\"gzr\").value;\r\n\t\tvar locale = document.getElementById(''locale'').value;\r\n        var url = \"/cbweb-pbc-web/pbc/query?&workTime=\"+workTime+\"&locale=\"+locale;\r\n\r\n        $.ajax({\r\n            type : \"post\",\r\n            url : url,\r\n            cache : false,\r\n            success : function(data) {\r\n                createGraph(data);\r\n            },\r\n            error : function() {\r\n                alert(LoadingDataFailedMsg);\r\n                $(''#graph'').html(\"\");\r\n                return;\r\n            }\r\n        });\r\n    }\r\n\r\n    var url = window.location.href;\r\n    var locale=url.substring(url.indexOf(\"=\") + 1, url.length).split(''&'');\r\n\tif ( locale !== ''en_US'') {\r\n\t\tlocale = ''zh_CN''\r\n\t}\r\n\r\n    function queryGjqxInfo(){\r\n        var workTime = [document.getElementById(\"gzr\").value];\r\n\t\tvar locale = document.getElementById(''locale'').value;\r\n        var url = \"/cbweb-pbc-web/pbc/queryGjqxInfo?&workTime=\"+workTime+\"&locale=\"+locale;\r\n\r\n        $.ajax({\r\n            type : \"post\",\r\n            url : url,\r\n            cache : false,\r\n            dataType : \"html\",\r\n            success : function(data) {\r\n                $(\"#gjqxData\").html(data);\r\n            }\r\n        });\r\n    }\r\n\r\n\r\n\r\n    function historyQuery(){\r\n    \tvar localeValue = document.getElementById(''locale'').value;\r\n\t\tif(localeValue ==\"en_US\" ){\r\n\t\t\twindow.open (''/cbweb-pbc-web/pbc/showHistory?locale=''+localeValue,''newwindow'',''height=550,width=1145,top=0,left=0,toolbar=no,menubar=no,scrollbars=yes,resizable=yes,location=no,status=no'');\r\n\t\t}else{\r\n\t\t\twindow.open (''/cbweb-pbc-web/pbc/showHistory?locale=zh_CN'',''newwindow'',''height=550,width=980,top=0,left=0,toolbar=no,menubar=no,scrollbars=yes,resizable=yes,location=no,status=no'');\r\n\t\t}\r\n    }\r\n\r\n\r\n\r\n    function showInfo(msgInfo,title){\r\n        alert(msgInfo);\r\n    }\r\n\r\n    var zero;\r\n    var year;\r\n    var month;\r\n    var dataNullMsg;\r\n    var LoadingDataFailedMsg;\r\n    $(document).ready(function(){\r\n        if(false){\r\n            zero = \"O/N\";\r\n            year = \"Y\";\r\n            month = \"M\";\r\n            dataNullMsg = \"No matched yield curve is found,please trying other searching criteria.\";\r\n            LoadingDataFailedMsg = \"Loading data failed\";\r\n        }else{\r\n            zero = \"0\";\r\n            year = \"年\";\r\n            month = \"月\";\r\n            dataNullMsg = \"没有查询到曲线,请重新输入查询条件\";\r\n            LoadingDataFailedMsg = \"取得数据失败\";\r\n        }\r\n\r\n        pbcInit();\r\n    });\r\n\r\n    function pbcInit(){\r\n        var locale = document.getElementById(''locale'').value;\r\n        var url = \"/cbweb-pbc-web/pbc/pbcInit?&locale=\"+locale;\r\n\r\n        $.ajax({\r\n            type : \"post\",\r\n            url : url,\r\n            cache : false,\r\n            success : function(data) {\r\n                createGraph(data);\r\n            },\r\n            error : function() {\r\n                alert(LoadingDataFailedMsg);\r\n                $(''#graph'').html(\"\");\r\n                return;\r\n            }\r\n        });\r\n    }\r\n\r\n    function createGraph(data){\r\n\r\n        if(data == null || data.length == 0){\r\n            alert(dataNullMsg);\r\n            $(''#graph'').html(\"\");\r\n            return;\r\n        }\r\n\r\n        var tempData;\r\n\r\n        options.series = new Array();\r\n        for(var i = 0; i < data.length; i++){\r\n            var yData = new Array();\r\n            options.series[i]=new Object();\r\n\r\n            tempData = data[i].seriesData;\r\n            for(var j = 0; j < tempData.length; j++){\r\n\r\n                var xValue = tempData[j][0];\r\n                if(xValue == 0){\r\n                    xData.push(zero);\r\n                }else if(xValue > 0 && xValue < 1){\r\n                    xData.push(xValue * 12 + month);\r\n                }else if(xValue >= 1){\r\n                    xData.push(xValue + year);\r\n                }else{\r\n                    xData.push(xValue);\r\n                }\r\n\r\n                var yValue;\r\n                if(xValue < 0.25){\r\n                    yValue = \"\";\r\n                }else{\r\n                    yValue = Number(tempData[j][1]);\r\n                }\r\n                if(xValue == 0.25 || xValue == 0.5 || xValue == 1 || xValue == 3\r\n                    || xValue == 5 || xValue == 7 || xValue == 10 || xValue == 30){\r\n                    yData.push({y:yValue,marker:{radius:2}});\r\n                }else{\r\n                    yData.push(yValue);\r\n                }\r\n                options.series[i].data = yData;\r\n                options.series[i].name = data[i].ycDefName;\r\n                options.series[i].color = colorArr[i];\r\n                options.series[i].dataGrouping = {enabled : false};\r\n                options.series[i].lineWidth = 1;\r\n            }\r\n\r\n        }\r\n\r\n        chart = new Highcharts.Chart(options);\r\n    }\r\n\r\n</script>\r\n</html>","headers":{"Vary":"Accept-Encoding","Content-Type":"text/html;charset=UTF-8","Date":"Sun, 11 Oct 2026 10:30:06 GMT","Connection":"keep-alive","Content-Language":"und","X-Frame-Options":"allowall","Set-Cookie":"JSESSIONID=24AB9C98D33CE3DFF7F6C6C7EC902CFD; Path=/cbweb-pbc-web; HttpOnly","X-Content-Type-Options":"nosniff","Strict-Transport-Security":"max-age=30; includeSubDomains;","X-Xss-Protection":"1; mode=block","Expect-Ct":"enforce; max-age=86400"},"status_code":200}', 'reczz28M4SLQHSt2'),
