(83, 'CJH-SX-LEVEL|2026/10/15 18:30', 'CJH-SX-LEVEL', 'http://www.cjh.com.cn/sqindex.html', '米', '2026-10-15T18:30:07.105+08:00', '完成（新增或已去重）', '{"status_code":200,"$startTime":1792060210059,"$endTime":1792060211398,"body":"<html lang=\"zh-CN\" xmlns=\"http://www.w3.org/1999/xhtml\">\r\n\r\n\t<head>\r\n\t\t<meta charset=\"utf-8\">\r\n\t\t<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\" />\r\n\t\t<title>水情信息</title>\r\n\t\t<meta name=\"viewport\" content=\"width=device-width, initial-scale=1,maximum-scale=1, user-scalable=no\">\r\n\t\t<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\r\n\t\t<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black\">\r\n\t\t<link rel=\"stylesheet\" href=\"assetscjsw/styles/reset.css\" />\r\n\t\t<link rel=\"stylesheet\" href=\"assetscjsw/styles/common.css\" />\r\n\t\t<link rel=\"stylesheet\" href=\"assetscjsw/styles/index.css\" />\r\n<style>\r\n.sssq tr{border-top: 1px solid #e7ecf1;}\r\n</style>\r\n\t</head>\r\n\r\n\t<body>\r\n<table class=''sssq'' width=\"100%\" cellspacing=\"1\" cellpadding=\"1\">\r\n\t\t\t<tbody id=\"sssqold\">\r\n\t\t\t</tbody>\r\n\t\t</table>\r\n<script type=\"text/javascript\" src=\"assetscjsw/plugin/jquery.min.js\"></script>\r\n\t\t<script type=\"text/javascript\">\r\n\t\t\tloadSQ();\r\n\t\t\t// 加载水情数据\r\n\t\t\tfunction loadSQ() {\r\n\t\t\t\tvar sssq = [{\"q\":\"8590\",\"rvnm\":\"长江干流\",\"stcd\":\"60105400\",\"stnm\":\"寸滩\",\"tm\":1792058400000,\"wptn\":\"4\",\"z\":\"173.600\"},{\"q\":\"1440\",\"rvnm\":\"乌江\",\"stcd\":\"60803000\",\"stnm\":\"武隆\",\"tm\":1792058400000,\"wptn\":\"5\",\"z\":\"175.150\"},{\"q\":\"12600\",\"rvnm\":\"长江干流\",\"stcd\":\"60107300\",\"stnm\":\"宜昌\",\"tm\":1792058400000,\"wptn\":\"5\",\"z\":\"42.180\"},{\"q\":\"12000\",\"rvnm\":\"长江干流\",\"stcd\":\"60108300\",\"stnm\":\"沙市\",\"tm\":1792058400000,\"wptn\":\"6\",\"z\":\"32.650\"},{\"rvnm\":\"长江干流\",\"stcd\":\"60111200\",\"stnm\":\"莲花塘\",\"tm\":1792058400000,\"wptn\":\"5\",\"z\":\"23.320\"},{\"q\":\"17100\",\"rvnm\":\"长江干流\",\"stcd\":\"60112200\",\"stnm\":\"汉口\",\"tm\":1792058400000,\"wptn\":\"6\",\"z\":\"16.660\"},{\"q\":\"16500\",\"rvnm\":\"长江干流\",\"stcd\":\"60113400\",\"stnm\":\"九江\",\"tm\":1792058400000,\"wptn\":\"6\",\"z\":\"10.740\"},{\"q\":\"18600\",\"rvnm\":\"长江干流\",\"stcd\":\"60115000\",\"stnm\":\"大通\",\"tm\":1792058400000,\"wptn\":\"4\",\"z\":\"6.620\"},{\"q\":\"5580\",\"rvnm\":\"洞庭湖湖口\",\"stcd\":\"61512000\",\"stnm\":\"七里山\",\"tm\":1792058400000,\"wptn\":\"5\",\"z\":\"23.360\"},{\"q\":\"1560\",\"rvnm\":\"鄱阳湖\",\"stcd\":\"62601600\",\"stnm\":\"湖口\",\"tm\":1792058400000,\"wptn\":\"6\",\"z\":\"9.900\"},{\"rvnm\":\"长江\",\"stcd\":\"60107000\",\"stnm\":\"茅坪(二)\",\"tm\":1792058400000,\"wptn\":\"4\",\"z\":\"172.970\"},{\"oq\":\"13400\",\"rvnm\":\"长江干流\",\"stcd\":\"60106980\",\"stnm\":\"三峡水库\",\"tm\":1792058400000,\"wptn\":\"4\",\"z\":\"172.970\"},{\"rvnm\":\"汉江\",\"stcd\":\"61802500\",\"stnm\":\"龙王庙\",\"tm\":1792058400000,\"wptn\":\"6\",\"z\":\"165.980\"},{\"oq\":\"1080\",\"q\":\"781\",\"rvnm\":\"汉江\",\"stcd\":\"61802700\",\"stnm\":\"丹江口水库\",\"tm\":1792058400000,\"wptn\":\"6\",\"z\":\"165.980\"}];\r\n\t\t\t\t\r\n\t\t\t\tvar sqHtml = \"<tr><td class=''tb1''><b>站名</b></td><td class=''tb1''><b>时间</b></td><td class=''tb1''><b>水位</b>(m)</td><td class=''tb1'' style=''padding-bottom: 3px;''><b>流量</b>(m<sup>3</sup>/s)</td></tr>\";\r\n\t\t\t\tfor(var i = 0; i < sssq.length; i++) {\r\n\t\t\t\t\tvar sssqTmp = sssq[i]\r\n\t\t\t\t\tvar trClass=\"\";\r\n\t\t\t\t\tif(i%2==0){\r\n\t\t\t\t\t\ttrClass=\"tb0\";\r\n\t\t\t\t\t}else{\r\n\t\t\t\t\t\ttrClass=\"tb1\";\r\n\t\t\t\t\t}\r\n\t\t\t\t\tvar z = \"-\";\r\n\t\t\t\t\tvar q = \"-\";\r\n\t\t\t\t\tvar oq = \"-\";\r\n\t\t\t\t\tvar wptnColor = \"\";\r\n\t\t\t\t\tif(sssqTmp.z) {\r\n\t\t\t\t\t\tz = (sssqTmp.z * 1).toFixed(2);\r\n\t\t\t\t\t}\r\n\t\t\t\t\tif(sssqTmp.q > 0) {\r\n\t\t\t\t\t\tq = (sssqTmp.q * 1).toFixed(0);\r\n\t\t\t\t\t}\r\n\t\t\t\t\tif(sssqTmp.oq > 0) {\r\n\t\t\t\t\t\toq = (sssqTmp.oq * 1).toFixed(0);\r\n\t\t\t\t\t}\r\n\t\t\t\t\tif(sssqTmp.wptn == 4) {\r\n\t\t\t\t\t\t// 落\r\n\t\t\t\t\t\twptnColor = ''#009900'';\r\n\t\t\t\t\t} else if(sssqTmp.wptn == 5) {\r\n\t\t\t\t\t\t// 涨\r\n\t\t\t\t\t\twptnColor = ''#ff0000'';\r\n\t\t\t\t\t}\r\n\t\t\t\t\tvar ioqTd = ''<td class=\"''+trClass+''\">'' + q + ''</td>'';\r\n\t\t\t\t\tif(oq != ''-'') {\r\n\t\t\t\t\t\tioqTd = ''<td class=\"''+trClass+''\">'' + q + ''(入)<br/>'' + oq + ''(出)'' + ''</td>'';\r\n\t\t\t\t\t}\r\n\t\t\t\t\t\r\n\t\t\t\t\tsqHtml += ''<tr><td class=\"''+trClass+''\"><a href=\"#''+sssqTmp.stcd+''\" >'' + sssqTmp.stnm + ''</a></td><td class=\"''+trClass+''\">'' + getTime(sssqTmp.tm) + ''</td><td class=\"''+trClass+''\"><font color=\"'' + wptnColor + ''\">'' + z + ''</font></td>'' + ioqTd + ''</tr>'';\r\n\r\n//sqHtml += ''<tr><td class=\"''+trClass+''\"><a href=\"#\" >'' + sssqTmp.stnm + ''</a></td><td class=\"''+trClass+''\">'' + sssqTmp.tm + ''</td><td class=\"''+trClass+''\"><font color=\"'' + wptnColor + ''\">'' + z + ''</font></td>'' + ioqTd + ''</tr>'';\r\n\t\t\t\t}\r\n$(\"#sssqold\").html(sqHtml);\r\n\t\t\t}\r\n\r\n\t\t\tfunction getTime(ntime) {\r\nif(ntime==''-''){return ''-'';}\r\n\t\t\t\tvar now = new Date(ntime);\r\n\t\t\t\tvar year = now.getYear();\r\n\t\t\t\tvar month = now.getMonth() + 1;\r\n\t\t\t\tvar date = now.getDate();\r\n\t\t\t\tvar hour = now.getHours();\r\n\t\t\t\tvar minute = now.getMinutes();\r\n\t\t\t\tvar second = now.getSeconds();\r\n\t\t\t\treturn PrefixInteger(date, 2) + \"日 \" + PrefixInteger(hour, 2) + \"时\"+PrefixInteger(minute, 2) + \"分\";;\r\n\r\n\t\t\t}\r\n\t\t\tfunction PrefixInteger(num, n) {\r\n\t\t\t\treturn(Array(n).join(0) + num).slice(-n);\r\n\t\t\t}\r\n\r\nwindow.addEventListener(''message'',function(rs){\r\n    var pointdata=rs.data;\r\nif(pointdata==''refresh''){\r\n     window.location.reload();\r\n}else{\r\nconsole.log(pointdata);\r\n}\r\n})\r\n</script>\r\n\t</body>\r\n\r\n</html>\r\n","headers":{"Content-Type":"text/html;charset=utf-8","Date":"Thu, 15 Oct 2026 10:30:24 GMT","Server":"nginx","Set-Cookie":"WJSESSIONID=032DB068A70DF8BAFFA3C0E0081E3FDA; Path=/; HttpOnly","X-Bd-Remote-Connection-Info":"lf-lf02-bgp; bind=123.58.10.238; local=123.58.10.238:13418; remote=219.140.196.72:80","X-Bd-Upstream-Id":"lf-lf02-bgp","Connection":"Keep-Alive"}}', 'reczz28Neavd6V5W'),
