(85, 'CJH-SX-LEVEL|2026/10/16 18:30', 'CJH-SX-LEVEL', 'http://www.cjh.com.cn/sqindex.html', '米', '2026-10-16T18:30:03.489+08:00', '完成（新增或已去重）', '{"body":"<html lang=\"zh-CN\" xmlns=\"http://www.w3.org/1999/xhtml\">\r\n\r\n\t<head>\r\n\t\t<meta charset=\"utf-8\">\r\n\t\t<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\" />\r\n\t\t<title>水情信息</title>\r\n\t\t<meta name=\"viewport\" content=\"width=device-width, initial-scale=1,maximum-scale=1, user-scalable=no\">\r\n\t\t<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\r\n\t\t<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black\">\r\n\t\t<link rel=\"stylesheet\" href=\"assetscjsw/styles/reset.css\" />\r\n\t\t<link rel=\"stylesheet\" href=\"assetscjsw/styles/common.css\" />\r\n\t\t<link rel=\"stylesheet\" href=\"assetscjsw/styles/index.css\" />\r\n<style>\r\n.sssq tr{border-top: 1px solid #e7ecf1;}\r\n</style>\r\n\t</head>\r\n\r\n\t<body>\r\n<table class=''sssq'' width=\"100%\" cellspacing=\"1\" cellpadding=\"1\">\r\n\t\t\t<tbody id=\"sssqold\">\r\n\t\t\t</tbody>\r\n\t\t</table>\r\n<script type=\"text/javascript\" src=\"assetscjsw/plugin/jquery.min.js\"></script>\r\n\t\t<script type=\"text/javascript\">\r\n\t\t\tloadSQ();\r\n\t\t\t// 加载水情数据\r\n\t\t\tfunction loadSQ() {\r\n\t\t\t\tvar sssq = [{\"q\":\"8930\",\"rvnm\":\"长江干流\",\"stcd\":\"60105400\",\"stnm\":\"寸滩\",\"tm\":1792144800000,\"wptn\":\"4\",\"z\":\"173.560\"},{\"q\":\"678\",\"rvnm\":\"乌江\",\"stcd\":\"60803000\",\"stnm\":\"武隆\",\"tm\":1792144800000,\"wptn\":\"4\",\"z\":\"173.670\"},{\"q\":\"12600\",\"rvnm\":\"长江干流\",\"stcd\":\"60107300\",\"stnm\":\"宜昌\",\"tm\":1792144800000,\"wptn\":\"5\",\"z\":\"42.190\"},{\"q\":\"12000\",\"rvnm\":\"长江干流\",\"stcd\":\"60108300\",\"stnm\":\"沙市\",\"tm\":1792144800000,\"wptn\":\"4\",\"z\":\"32.730\"},{\"rvnm\":\"长江干流\",\"stcd\":\"60111200\",\"stnm\":\"莲花塘\",\"tm\":1792144800000,\"wptn\":\"5\",\"z\":\"23.930\"},{\"q\":\"18200\",\"rvnm\":\"长江干流\",\"stcd\":\"60112200\",\"stnm\":\"汉口\",\"tm\":179214480000