eft; line-height: 1\">中债国债收益率曲线</td>\r\n                      <!--  <td style=\"border-left:1px solid #000000\">0.9331 </td> -->\r\n                       <td style=\"border-left:1px solid #000000\">1.1568</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.1587</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.1703</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.2729</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.3815</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.4700</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.6480</td>\r\n                       <td style=\"border-left:1px solid #000000\">2.0600</td>\r\n\t\t\t\t    </tr>\r\n\t\t\t\t\r\n\t\t\t\t    <tr>\r\n\t\t\t\t       <td style=\"width: 250px;text-align: left; line-height: 1\">中债商业银行普通债收益率曲线(AAA)</td>\r\n                      <!--  <td style=\"border-left:1px solid #000000\">1.3041 </td> -->\r\n                       <td style=\"border-left:1px solid #000000\">1.4100</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.4217</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.4520</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.5331</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.5504</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.6717</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.8006</td>\r\n                       <td style=\"border-left:1px solid #000000\">2.2505</td>\r\n\t\t\t\t    </tr>\r\n\t\t\t\t\r\n\t\t\t\t    <tr>\r\n\t\t\t\t       <td style=\"width: 250px;text-align: left; line-height: 1\">中债中短期票据收益率曲线(AAA)</td>\r\n                      <!--  <td style=\"border-left:1px solid #000000\">1.4055 </td> -->\r\n                       <td style=\"border-left:1px solid #000000\">1.4402</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.4657</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.4764</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.5918</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.6673</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.7815</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.8976</td>\r\n                       <td style=\"border-left:1px solid #000000\"></td>\r\n\t\t\t\t    </tr>\r\n\t\t\t\t\r\n\t\t\t</table>\r\n\t\t</div>\r\n\t\t<div id=\"zhu\"> <!-- 注：表中三个月期限国债收益率是用于计算SDR利率的人民币代表性利率 -->注：&nbsp;表中三个月期限国债收益率是用于计算SDR利率的人民币代表性利率</div>\r\n\t\t<div id=\"font1\">\r\n\t\t\t\r\n\t\t\t\t<div style=\"font-weight:bold; text-align: center;\">\r\n\t\t               <!-- 国债及其他收益率曲线简介 -->国债及其他债券收益率曲线简介\r\n\t\t    \t</div>\r\n\t\t\t\r\n\t\t      <div>\r\n\t\t         &nbsp; &nbsp; <!-- 国债及其他收益率曲线是由中央国债登记结算有限责任公司(www.chinabond.com.cn)编制提供的一组反映在岸人民币债券市场到期收益率走势的图表。\r\n\t\t                            其中，国债收益率曲线样本包括记账式附息国债和记账式贴现国债；AAA级商业银行普通债曲线样本包括同业存单和商业银行债券；AAA级中短期票据曲线样本包括AAA级超短期融资券、短期融资券和中期票据 -->\r\n\t\t                            国债及其他债券收益率曲线是由中央国债登记结算有限责任公司(www.chinabond.com.cn)编制提供的一组反映在岸人民币债券市场到期收益率走势的图表。其中，国债收益率曲线样本包括记账式附息国债和记账式贴现国债；AAA级商业银行普通债收益率曲线样本包括同业存单和商业银行债券；AAA级中短期票据收益率曲线样本包括AAA级超短期融资券、短期融资券和中期票据。\r\n\t\t      </div>\r\n\t\t      <div>\r\n\t\t        &nbsp; &nbsp; <!-- 中债收益率曲线包括国债在内的各信用等级的到期、即期和远期收益曲线约1000余条，采用赫尔米特模型编制。曲线数据源包括银行间市场和交易所市场的做市商报价、\r\n\t\t                       货币经纪公司报价、成交价和结算价等。收益率曲线的样本点优先选取新发行且满足流动性要求的债券。中债收益率曲线每个工作日日终发布一次，发布时间为北京时间17:30 -->\r\n\t\t                           中债收益率曲线包括国债在内的各信用等级的到期、即期和远期收益曲线约1000余条，采用赫尔米特模型编制。曲线数据源包括银行间市场和交易所市场的做市商报价、货币经纪公司报价、成交价和结算价等。收益率曲线的样本点优先选取新发行且满足流动性要求的债券。中债收益率曲线每个工作日日终发布一次，发布时间为北京时间17:30。\r\n\t\t     </div>\r\n\t\t</div>\r\n\t</div>\r\n\t<input type=\"hidden\" id=\"locale\" value=\"cn_ZH\">\r\n</body>\r\n\r\n<script type=\"text/javascript\">\r\n\r\n    Highcharts.setOptions({\r\n        global: {\r\n            useUTC: false\r\n        },\r\n    });\r\n    var chart = null;\r\n    var xData=new Array();\r\n    var options = {\r\n        chart : {\r\n            exporting : {\r\n                enabled : true //用来设置是否显示‘打印’,''导出''等功能按钮，不设置时默认为显示\r\n            },\r\n            renderTo : ''graph'',\r\n            type: ''line'',\r\n            marginBottom : 90,\r\n            marginTop : 5,\r\n            marginLeft : 50,\r\n        },\r\n        title : {\r\n            text : ''''\r\n        },\r\n        xAxis : {\r\n            labels:{\r\n                style:{\r\n                    fontSize:''10px'',\r\n                    fontFamily: \"宋体\",\r\n                    color: \"#333333\",\r\n                }\r\n            },\r\n            crosshair: {\r\n                width: 1,\r\n                color: ''#CC0000''\r\n            },\r\n            categories:xData,\r\n            tickPositions: [0,10, 20,30, 50,70,110],\r\n            tickWidth : 1,\r\n            gridLineWidth : 1,\r\n            lineWidth : 1,\r\n            lineColor : ''black'',\r\n            showFirstLabel : true,\r\n            showLastLable : true,\r\n            tickLength : 0,\r\n        },\r\n\r\n        yAxis : [ {\r\n            labels : {\r\n                format : ''{value:.,0f}'',\r\n                padding : 50,\r\n                x : -10,\r\n                formatter : function(){\r\n                    return this.value.toFixed(2);//这里是两位小数，你要几位小数就改成几\r\n                },\r\n                style:{\r\n                    fontWeight:\"normal\",\r\n                    fontSize: \"10px\",\r\n                    fontFamily: \"宋体\",\r\n                    color: \"#333333\",\r\n                }\r\n            },\r\n            title : {\r\n                text : ''(%)'',\r\n                align: ''high'',\r\n                offset: 5,\r\n                rotation:0,\r\n                y: 85,\r\n                x: -30,\r\n                style:{\r\n                    fontWeight:\"normal\",\r\n                    fontSize: \"10px\",\r\n                    fontFamily: \"宋体\",\r\n                    color: \"#333333\",\r\n                }\r\n            },\r\n            tickPixelInterval: 50,\r\n            allowDecimals : true,//是否显示小数\r\n            showFirstLabel : true,\r\n            tickPosition : ''outside'',\r\n            tickLength : 3,\r\n            opposite : false,//设置y轴在对面显示\r\n            lineWidth : 1,//设置y轴的线宽\r\n            tickWidth : 1,\r\n            tickColor : ''black'',\r\n            lineColor : ''black'',\r\n        } ],\r\n\r\n        legend : {\r\n            enabled : true,\r\n            align: ''left'',\r\n            layout: ''vertical'',\r\n            floating: true,\r\n            itemMarginTop: 3,\r\n            x: 45,\r\n            y: 10,\r\n            itemStyle: {\r\n                fontWeight:\"normal\",\r\n                fontSize: \"12px\",\r\n                fontFamily: \"宋体\",\r\n                color: \"#333333\",\r\n                cursor: \"default\",\r\n            },\r\n        },\r\n        credits : {\r\n            enabled : false //去掉higcharts.com\r\n        },\r\n        tooltip : {\r\n            shared : false,\r\n            split : true,\r\n            animation : false,\r\n            shape : ''square'',\r\n            crosshairs : {\r\n                width : 1,\r\n                color : ''red''\r\n            },\r\n            distance : 3,//距离某个点的距离\r\n            useHTML : true,\r\n            borderWidth : 1,\r\n            headerFormat : ''<small style=\"background-color:#DC143C\">{point.key}</small><table border=\"5\">'',\r\n            pointFormat : ''<tr><td style=\"text-align: right,color:{point.color}\">{point.y:.4f}%</td></tr>'',\r\n            footerFormat : ''</table>'',\r\n        },\r\n        plotOptions : {\r\n            series: {\r\n                animation:false,\r\n                states:{\r\n                    hover:{\r\n                        lineWidthPlus: 0\r\n                    },\r\n                },\r\n                marker:{\r\n                    symbol:''circle'',\r\n                    enabled:true,\r\n                    radius:0.1\r\n                },\r\n                connectNulls:true,//连接空点\r\n            },\r\n        },\r\n        series : []\r\n    }\r\n    function query(){\r\n        queryGjqxInfo();\r\n\r\n        var workTime=document.getElementById(\"gzr\").value;\r\n\t\tvar locale = document.getElementById(''locale'').value;\r\n        var url = \"/cbweb-pbc-web/pbc/query?&workTime=\"+workTime+\"&locale=\"+locale;\r\n\r\n        $.ajax({\r\n            type : \"post\",\r\n            url : url,\r\n            cache : false,\r\n            success : function(data) {\r\n                createGraph(data);\r\n            },\r\n            error : function() {\r\n                alert(LoadingDataFailedMsg);\r\n                $(''#graph'').html(\"\");\r\n                return;\r\n            }\r\n        });\r\n    }\r\n\r\n    var url = window.location.href;\r\n    var locale=url.substring(url.indexOf(\"=\") + 1, url.length).split(''&'');\r\n\tif ( locale !== ''en_US'') {\r\n\t\tlocale = ''zh_CN''\r\n\t}\r\n\r\n    function queryGjqxInfo(){\r\n        var workTime = [document.getElementById(\"gzr\").value];\r\n\t\tvar locale = document.getElementById(''locale'').value;\r\n        var url = \"/cbweb-pbc-web/pbc/queryGjqxInfo?&workTime=\"+workTime+\"&locale=\"+locale;\r\n\r\n        $.ajax({\r\n            type : \"post\",\r\n            url : url,\r\n            cache : false,\r\n            dataType : \"html\",\r\n            success : function(data) {\r\n                $(\"#gjqxData\").html(data);\r\n            }\r\n        });\r\n    }\r\n\r\n\r\n\r\n    function historyQuery(){\r\n    \tvar localeValue = document.getElementById(''locale'').value;\r\n\t\tif(localeValue ==\"en_US\" ){\r\n\t\t\twindow.open (''/cbweb-pbc-web/pbc/showHistory?locale=''+localeValue,''newwindow'',''height=550,width=1145,top=0,left=0,toolbar=no,menubar=no,scrollbars=yes,resizable=yes,location=no,status=no'');\r\n\t\t}else{\r\n\t\t\twindow.open (''/cbweb-pbc-web/pbc/showHistory?locale=zh_CN'',''newwindow'',''height=550,width=980,top=0,left=0,toolbar=no,menubar=no,scrollbars=yes,resizable=yes,location=no,status=no'');\r\n\t\t}\r\n    }\r\n\r\n\r\n\r\n    function showInfo(msgInfo,title){\r\n        alert(msgInfo);\r\n    }\r\n\r\n    var zero;\r\n    var year;\r\n    var month;\r\n    var dataNullMsg;\r\n    var LoadingDataFailedMsg;\r\n    $(document).ready(function(){\r\n        if(false){\r\n            zero = \"O/N\";\r\n            year = \"Y\";\r\n            month = \"M\";\r\n            dataNullMsg = \"No matched yield curve is found,please trying other searching criteria.\";\r\n            LoadingDataFailedMsg = \"Loading data failed\";\r\n        }else{\r\n            zero = \"0\";\r\n            year = \"年\";\r\n            month = \"月\";\r\n            dataNullMsg = \"没有查询到曲线,请重新输入查询条件\";\r\n            LoadingDataFailedMsg = \"取得数据失败\";\r\n        }\r\n\r\n        pbcInit();\r\n    });\r\n\r\n    function pbcInit(){\r\n        var locale = document.getElementById(''locale'').value;\r\n        var url = \"/cbweb-pbc-web/pbc/pbcInit?&locale=\"+locale;\r\n\r\n        $.ajax({\r\n            type : \"post\",\r\n            url : url,\r\n            cache : false,\r\n            success : function(data) {\r\n                createGraph(data);\r\n            },\r\n            error : function() {\r\n                alert(LoadingDataFailedMsg);\r\n                $(''#graph'').html(\"\");\r\n                return;\r\n            }\r\n        });\r\n    }\r\n\r\n    function createGraph(data){\r\n\r\n        if(data == null || data.length == 0){\r\n            alert(dataNullMsg);\r\n            $(''#graph'').html(\"\");\r\n            return;\r\n        }\r\n\r\n        var tempData;\r\n\r\n        options.series = new Array();\r\n        for(var i = 0; i < data.length; i++){\r\n            var yData = new Array();\r\n            options.series[i]=new Object();\r\n\r\n            tempData = data[i].seriesData;\r\n            for(var j = 0; j < tempData.length; j++){\r\n\r\n                var xValue = tempData[j][0];\r\n                if(xValue == 0){\r\n                    xData.push(zero);\r\n                }else if(xValue > 0 && xValue < 1){\r\n                    xData.push(xValue * 12 + month);\r\n                }else if(xValue >= 1){\r\n                    xData.push(xValue + year);\r\n                }else{\r\n                    xData.push(xValue);\r\n                }\r\n\r\n                var yValue;\r\n                if(xValue < 0.25){\r\n                    yValue = \"\";\r\n                }else{\r\n                    yValue = Number(tempData[j][1]);\r\n                }\r\n                if(xValue == 0.25 || xValue == 0.5 || xValue == 1 || xValue == 3\r\n                    || xValue == 5 || xValue == 7 || xValue == 10 || xValue == 30){\r\n                    yData.push({y:yValue,marker:{radius:2}});\r\n                }else{\r\n                    yData.push(yValue);\r\n                }\r\n                options.series[i].data = yData;\r\n                options.series[i].name = data[i].ycDefName;\r\n                options.series[i].color = colorArr[i];\r\n                options.series[i].dataGrouping = {enabled : false};\r\n                options.series[i].lineWidth = 1;\r\n            }\r\n\r\n        }\r\n\r\n        chart = new Highcharts.Chart(options);\r\n    }\r\n\r\n</script>\r\n</html>","headers":{"Set-Cookie":"JSESSIONID=0AD014FA9D59CCC5255436AB20FF8F26; Path=/cbweb-pbc-web; HttpOnly","Vary":"Accept-Encoding","Content-Type":"text/html;charset=UTF-8","Expect-Ct":"enforce; max-age=86400","X-Content-Type-Options":"nosniff","Content-Language":"und","Strict-Transport-Security":"max-age=30; includeSubDomains;","X-Frame-Options":"allowall","Date":"Sat, 17 Oct 2026 10:30:10 GMT","Connection":"keep-alive","X-Xss-Protection":"1; mode=block"},"status_code":200}', 'reczz28ORf8x6nAe'),
(91, 'TENCENT-600900|2026/10/18 18:30', 'TENCENT-600900', 'https://qt.gtimg.cn/q=sh600900', '元', '2026-10-18T18:30:01.493+08:00', '完成（重复观察未新增）', '{"$endTime":1792319405485,"body":"v_sh600900=\"1~��������~600900~29.38~29.60~29.38~1427959~752627~675332~29.37~230~29.35~3~29.34~70~29.33~14~29.32~4034~29.38~565~29.39~3710~29.40~3057~29.41~956~29.42~977~~20261016161446~-0.22~-0.74~29.57~29.08~29.38/1427959/4185608058~1427959~418561~0.58~19.86~~29.57~29.08~1.66~7188.76~7188.76~3.33~32.56~26.64~1.24~-4914~29.31~24.36~20.84~~~-0.12~418560.8058~247.3796~842~   A~GP-A~12.18~1.35~3.40~16.75~6.54~29.63~24.38~3.60~4.59~7.03~24468217716~24468217716~-36.09~13.83~24468217716~~~8.17~-0.07~~CNY~0~___D__F__N~29.44~-5569~\";\n","headers":{"Content-Type":"text/html; charset=GBK","Date":"Sun, 18 Oct 2026 10:30:05 GMT","Expires":"Sun, 18 Oct 2026 10:30:05 GMT","Server":"openresty/1.11.2.1","Access-Control-Allow-Origin":"*","Cache-Control":"max-age=0"},"status_code":200,"$startTime":1792319404640}', 'reczz28OqCBJ1U6F'),
(92, 'CHINABOND-CGB10Y|2026/10/18 18:30', 'CHINABOND-CGB10Y', 'https://yield.chinabond.com.cn/cbweb-pbc-web/pbc/more?locale=cn_zh', '%', '2026-10-18T18:30:03.692+08:00', '完成（重复观察未新增）', '{"body":"\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html>\r\n<head>\r\n\t<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\" />\r\n\t\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n <script type=\"text/javascript\" >\r\n        var ctx=\"/cbweb-pbc-web\";\r\n        var ctxStatics=\"/cbweb-pbc-web/statics\";\r\n </script>\r\n\r\n\r\n\r\n\t<meta http-equiv=\"Content-Type\" content=\"text/html;charset=utf-8\" />\n<meta http-equiv=\"Cache-Control\" content=\"no-store\" /><meta http-equiv=\"Pragma\" content=\"no-cache\" />\n<meta http-equiv=\"Expires\" content=\"0\" />\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\" />\n<script src=\"/cbweb-pbc-web/statics/js/jquery/jquery-1.9.1.min.js\" type=\"text/javascript\"></script>\n<script type=\"text/javascript\" src=\"/cbweb-pbc-web/statics/js/jquery-ztree/jquery.ztree.core-3.5.js\"></script>\n<script type=\"text/javascript\" src=\"/cbweb-pbc-web/statics/js/jquery-ztree/jquery.ztree.excheck-3.5.js\"></script>\n<script src=\"/cbweb-pbc-web/statics/My97DatePicker/WdatePicker.js\" type=\"text/javascript\"></script>\n\r\n<title>国债及其他债券收益率曲线</title>\r\n \r\n\r\n\t<link rel=\"stylesheet\" type=\"text/css\" href=\"/cbweb-pbc-web/statics/css/indexCn.css\" id=\"css\" />\r\n\r\n   \r\n<script src=\"/cbweb-pbc-web/statics/js/My97DatePicker/WdatePicker.js\"\r\n\ttype=\"text/javascript\"></script>\r\n\t\r\n<script src=\"/cbweb-pbc-web/statics/js/custom/statusCheck.js\"\r\n\ttype=\"text/javascript\"></script>\r\n\t\r\n<script src=\"/cbweb-pbc-web/statics/js/higchart/highstock_pbc.js\"\r\n\ttype=\"text/javascript\"></script>\r\n\t\r\n<script src=\"/cbweb-pbc-web/statics/js/higchart/colorArr.js\"\r\n\ttype=\"text/javascript\"></script>\r\n\r\n</head>\r\n<body>\r\n\t<div id=\"Container\">\r\n\t\t<div id=\"Header\">\r\n\t\t\t   <div id=\"title\"><!-- 国债及其他收益率曲线 -->国债及其他债券收益率曲线</div>\r\n\t           <div id=\"ytitle\">中央国债登记结算有限责任公司编制<!--  中央国债登记结算有限责任公司编制 --></div>\r\n\t\t</div>\r\n\t\t<div class=\"Clear\"></div>\r\n\t\t<div id=\"Content\">\r\n\t\t\t<div id=\"dateText\"><!-- 日期 -->日期:</div>\r\n\t\t\t<div id=\"datePop\">\r\n\t\t\t    \r\n\t\t        \r\n\t\t            <input name=\"gzr\" id=\"gzr\" type=\"text\" class=\"date\" value=\"2026-10-16\"\r\n\t\t\t\t\t\t\tonclick=\"WdatePicker({dateFmt:''yyyy-MM-dd'',isShowClear:false\r\n\t\t\t\t\t\t\t ,isShowToday:false,isShowOK:false,readOnly:true,lang:''zh-cn''});\" />\r\n\t\t        \r\n\t\t\t</div>\r\n\t\t\t<div id=\"searchBut\">\r\n\t\t\t    <input type=\"button\" value=\"查询\" onclick=\"query()\"/>\r\n\t\t\t\t<input type=\"button\" value=\"历史数据\" onclick=\"historyQuery()\"/>\r\n\t\t\t</div>\r\n\t\t</div>\r\n\t\t\r\n\t\t<div id = \"graph\" class=\"graph\" align=\"left\"></div>\r\n\t\t   \r\n\t\t<div id=\"gjqxData\">\r\n\t\t\t<table  border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\r\n\t\t\t\t <tr>\r\n\t\t\t\t \r\n\t\t\t\t    <th>2026-10-16(%)</th>\r\n\t\t\t\t\t<!--<th style=\"border-left:1px solid #000000\"> 隔夜 隔夜</th>-->\r\n\t\t\t\t    <th style=\"border-left:1px solid #000000\">3<!-- 月 -->月</th>\r\n\t\t\t\t    <th style=\"border-left:1px solid #000000\">6<!-- 月 -->月</th>\r\n\t\t\t\t    <th style=\"border-left:1px solid #000000\">1<!-- 年 -->年</th>\r\n\t\t\t\t    <th style=\"border-left:1px solid #000000\">3<!-- 年 -->年</th>\r\n\t\t\t\t    <th style=\"border-left:1px solid #000000\">5<!-- 年 -->年</th>\r\n\t\t\t\t    <th style=\"border-left:1px solid #000000\">7<!-- 年 -->年</th>\r\n\t\t\t\t    <th style=\"border-left:1px solid #000000\">10<!-- 年 -->年</th>\r\n\t\t\t\t    <th style=\"border-left:1px solid #000000\">30<!-- 年 -->年</th>\r\n\t\t\t\t</tr>\r\n\t\t\t\t\r\n\t\t\t\t    <tr>\r\n\t\t\t\t       <td style=\"width: 250px;text-align: left; line-height: 1\">中债国债收益率曲线</td>\r\n                      <!--  <td style=\"border-left:1px solid #000000\">0.9331 </td> -->\r\n                       <td style=\"border-left:1px solid #000000\">1.1568</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.1587</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.1703</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.2729</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.3815</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.4700</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.6480</td>\r\n                       <td style=\"border-left:1px solid #000000\">2.0600</td>\r\n\t\t\t\t    </tr>\r\n\t\t\t\t\r\n\t\t\t\t    <tr>\r\n\t\t\t\t       <td style=\"width: 250px;text-align: left; line-height: 1\">中债商业银行普通债收益率曲线(AAA)</td>\r\n                      <!--  <td style=\"border-left:1px solid #000000\">1.3041 </td> -->\r\n                       <td style=\"border-left:1px solid #000000\">1.4100</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.4217</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.4520</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.5331</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.5504</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.6717</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.8006</td>\r\n                       <td style=\"border-left:1px solid #000000\">2.2505</td>\r\n\t\t\t\t    </tr>\r\n\t\t\t\t\r\n\t\t\t\t    <tr>\r\n\t\t\t\t       <td style=\"width: 250px;text-align: left; line-height: 1\">中债中短期票据收益率曲线(AAA)</td>\r\n                      <!--  <td style=\"border-left:1px solid #000000\">1.4055 </td> -->\r\n                       <td style=\"border-left:1px solid #000000\">1.4402</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.4657</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.4764</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.5918</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.6673</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.7815</td>\r\n                       <td style=\"border-left:1px solid #000000\">1.8976</td>\r\n                       <td style=\"border-left:1px solid #000000\"></td>\r\n\t\t\t\t    </tr>\r\n\t\t\t\t\r\n\t\t\t</table>\r\n\t\t</div>\r\n\t\t<div id=\"zhu\"> <!-- 注：表中三个月期限国债收益率是用于计算SDR利率的人民币代表性利率 -->注：&nbsp;表中三个月期限国债收益率是用于计算SDR利率的人民币代表性利率</div>\r\n\t\t<div id=\"font1\">\r\n\t\t\t\r\n\t\t\t\t<div style=\"font-weight:bold; text-align: center;\">\r\n\t\t               <!-- 国债及其他收益率曲线简介 -->国债及其他债券收益率曲线简介\r\n\t\t    \t</div>\r\n\t\t\t\r\n\t\t      <div>\r\n\t\t         &nbsp; &nbsp; <!-- 国债及其他收益率曲线是由中央国债登记结算有限责任公司(www.chinabond.com.cn)编制提供的一组反映在岸人民币债券市场到期收益率走势的图表。\r\n\t\t                            其中，国债收益率曲线样本包括记账式附息国债和记账式贴现国债；AAA级商业银行普通债曲线样本包括同业存单和商业银行债券；AAA级中短期票据曲线样本包括AAA级超短期融资券、短期融资券和中期票据 -->\r\n\t\t                            国债及其他债券收益率曲线是由中央国债登记结算有限责任公司(www.chinabond.com.cn)编制提供的一组反映在岸人民币债券市场到期收益率走势的图表。其中，国债收益率曲线样本包括记账式附息国债和记账式贴现国债；AAA级商业银行普通债收益率曲线样本包括同业存单和商业银行债券；AAA级中短期票据收益率曲线样本包括AAA级超短期融资券、短期融资券和中期票据。\r\n\t\t      </div>\r\n\t\t      <div>\r\n\t\t        &nbsp; &nbsp; <!-- 中债收益率曲线包括国债在内的各信用等级的到期、即期和远期收益曲线约1000余条，采用赫尔米特模型编制。曲线数据源包括银行间市场和交易所市场的做市商报价、\r\n\t\t                       货币经纪公司报价、成交价和结算价等。收益率曲线的样本点优先选取新发行且满足流动性要求的债券。中债收益率曲线每个工作日日终发布一次，发布时间为北京时间17:30 -->\r\n\t\t                           中债收益率曲线包括国债在内的各信用等级的到期、即期和远期收益曲线约1000余条，采用赫尔米特模型编制。曲线数据源包括银行间市场和交易所市场的做市商报价、货币经纪公司报价、成交价和结算价等。收益率曲线的样本点优先选取新发行且满足流动性要求的债券。中债收益率曲线每个工作日日终发布一次，发布时间为北京时间17:30。\r\n\t\t     </div>\r\n\t\t</div>\r\n\t</div>\r\n\t<input type=\"hidden\" id=\"locale\" value=\"cn_ZH\">\r\n</body>\r\n\r\n<script type=\"text/javascript\">\r\n\r\n    Highcharts.setOptions({\r\n        global: {\r\n            useUTC: false\r\n        },\r\n    });\r\n    var chart = null;\r\n    var xData=new Array();\r\n    var options = {\r\n        chart : {\r\n            exporting : {\r\n                enabled : true //用来设置是否显示‘打印’,''导出''等功能按钮，不设置时默认为显示\r\n            },\r\n            renderTo : ''graph'',\r\n            type: ''line'',\r\n            marginBottom : 90,\r\n            marginTop : 5,\r\n            marginLeft : 50,\r\n        },\r\n        title : {\r\n            text : ''''\r\n        },\r\n        xAxis : {\r\n            labels:{\r\n                style:{\r\n                    fontSize:''10px'',\r\n                    fontFamily: \"宋体\",\r\n                    color: \"#333333\",\r\n                }\r\n            },\r\n            crosshair: {\r\n                width: 1,\r\n                color: ''#CC0000''\r\n            },\r\n            categories:xData,\r\n            tickPositions: [0,10, 20,30, 50,70,110],\r\n            tickWidth : 1,\r\n            gridLineWidth : 1,\r\n            lineWidth : 1,\r\n            lineColor : ''black'',\r\n            showFirstLabel : true,\r\n            showLastLable : true,\r\n            tickLength : 0,\r\n        },\r\n\r\n        yAxis : [ {\r\n            labels : {\r\n                format : ''{value:.,0f}'',\r\n                padding : 50,\r\n                x : -10,\r\n                formatter : function(){\r\n                    return this.value.toFixed(2);//这里是两位小数，你要几位小数就改成几\r\n                },\r\n                style:{\r\n                    fontWeight:\"normal\",\r\n                    fontSize: \"10px\",\r\n                    fontFamily: \"宋体\",\r\n                    color: \"#333333\",\r\n                }\r\n            },\r\n            title : {\r\n                text : ''(%)'',\r\n                align: ''high'',\r\n                offset: 5,\r\n                rotation:0,\r\n                y: 85,\r\n                x: -30,\r\n                style:{\r\n                    fontWeight:\"normal\",\r\n                    fontSize: \"10px\",\r\n                    fontFamily: \"宋体\",\r\n                    color: \"#333333\",\r\n                }\r\n            },\r\n            tickPixelInterval: 50,\r\n            allowDecimals : true,//是否显示小数\r\n            showFirstLabel : true,\r\n            tickPosition : ''outside'',\r\n            tickLength : 3,\r\n            opposite : false,//设置y轴在对面显示\r\n            lineWidth : 1,//设置y轴的线宽\r\n            tickWidth : 1,\r\n            tickColor : ''black'',\r\n            lineColor : ''black'',\r\n        } ],\r\n\r\n        legend : {\r\n            enabled : true,\r\n            align: ''left'',\r\n            layout: ''vertical'',\r\n            floating: true,\r\n            itemMarginTop: 3,\r\n            x: 45,\r\n            y: 10,\r\n            itemStyle: {\r\n                fontWeight:\"normal\",\r\n                fontSize: \"12px\",\r\n                fontFamily: \"宋体\",\r\n                color: \"#333333\",\r\n                cursor: \"default\",\r\n            },\r\n        },\r\n        credits : {\r\n            enabled : false //去掉higcharts.com\r\n        },\r\n        tooltip : {\r\n            shared : false,\r\n            split : true,\r\n            animation : false,\r\n            shape : ''square'',\r\n            crosshairs : {\r\n                width : 1,\r\n                color : ''red''\r\n            },\r\n            distance : 3,//距离某个点的距离\r\n            useHTML : true,\r\n            borderWidth : 1,\r\n            headerFormat : ''<small style=\"background-color:#DC143C\">{point.key}</small><table border=\"5\">'',\r\n            pointFormat : ''<tr><td style=\"text-align: right,color:{point.color}\">{point.y:.4f}%</td></tr>'',\r\n            footerFormat : ''</table>'',\r\n        },\r\n        plotOptions : {\r\n            series: {\r\n                animation:false,\r\n                states:{\r\n                    hover:{\r\n                        lineWidthPlus: 0\r\n                    },\r\n                },\r\n                marker:{\r\n                    symbol:''circle'',\r\n                    enabled:true,\r\n                    radius:0.1\r\n                },\r\n                connectNulls:true,//连接空点\r\n            },\r\n        },\r\n        series : []\r\n    }\r\n    function query(){\r\n        queryGjqxInfo();\r\n\r\n        var workTime=document.getElementById(\"gzr\").value;\r\n\t\tvar locale = document.getElementById(''locale'').value;\r\n        var url = \"/cbweb-pbc-web/pbc/query?&workTime=\"+workTime+\"&locale=\"+locale;\r\n\r\n        $.ajax({\r\n            type : \"post\",\r\n            url : url,\r\n            cache : false,\r\n            success : function(data) {\r\n                createGraph(data);\r\n            },\r\n            error : function() {\r\n                alert(LoadingDataFailedMsg);\r\n                $(''#graph'').html(\"\");\r\n                return;\r\n            }\r\n        });\r\n    }\r\n\r\n    var url = window.location.href;\r\n    var locale=url.substring(url.indexOf(\"=\") + 1, url.length).split(''&'');\r\n\tif ( locale !== ''en_US'') {\r\n\t\tlocale = ''zh_CN''\r\n\t}\r\n\r\n    function queryGjqxInfo(){\r\n        var workTime = [document.getElementById(\"gzr\").value];\r\n\t\tvar locale = document.getElementById(''locale'').value;\r\n        var url = \"/cbweb-pbc-web/pbc/queryGjqxInfo?&workTime=\"+workTime+\"&locale=\"+locale;\r\n\r\n        $.ajax({\r\n            type : \"post\",\r\n            url : url,\r\n            cache : false,\r\n            dataType : \"html\",\r\n            success : function(data) {\r\n                $(\"#gjqxData\").html(data);\r\n            }\r\n        });\r\n    }\r\n\r\n\r\n\r\n    function historyQuery(){\r\n    \tvar localeValue = document.getElementById(''locale'').value;\r\n\t\tif(localeValue ==\"en_US\" ){\r\n\t\t\twindow.open (''/cbweb-pbc-web/pbc/showHistory?locale=''+localeValue,''newwindow'',''height=550,width=1145,top=0,left=0,toolbar=no,menubar=no,scrollbars=yes,resizable=yes,location=no,status=no'');\r\n\t\t}else{\r\n\t\t\twindow.open (''/cbweb-pbc-web/pbc/showHistory?locale=zh_CN'',''newwindow'',''height=550,width=980,top=0,left=0,toolbar=no,menubar=no,scrollbars=yes,resizable=yes,location=no,status=no'');\r\n\t\t}\r\n    }\r\n\r\n\r\n\r\n    function showInfo(msgInfo,title){\r\n        alert(msgInfo);\r\n    }\r\n\r\n    var zero;\r\n    var year;\r\n    var month;\r\n    var dataNullMsg;\r\n    var LoadingDataFailedMsg;\r\n    $(document).ready(function(){\r\n        if(false){\r\n            zero = \"O/N\";\r\n            year = \"Y\";\r\n            month = \"M\";\r\n            dataNullMsg = \"No matched yield curve is found,please trying other searching criteria.\";\r\n            LoadingDataFailedMsg = \"Loading data failed\";\r\n        }else{\r\n            zero = \"0\";\r\n            year = \"年\";\r\n            month = \"月\";\r\n            dataNullMsg = \"没有查询到曲线,请重新输入查询条件\";\r\n            LoadingDataFailedMsg = \"取得数据失败\";\r\n        }\r\n\r\n        pbcInit();\r\n    });\r\n\r\n    function pbcInit(){\r\n        var locale = document.getElementById(''locale'').value;\r\n        var url = \"/cbweb-pbc-web/pbc/pbcInit?&locale=\"+locale;\r\n\r\n        $.ajax({\r\n            type : \"post\",\r\n            url : url,\r\n            cache : false,\r\n            success : function(data) {\r\n                createGraph(data);\r\n            },\r\n            error : function() {\r\n                alert(LoadingDataFailedMsg);\r\n                $(''#graph'').html(\"\");\r\n                return;\r\n            }\r\n        });\r\n    }\r\n\r\n    function createGraph(data){\r\n\r\n        if(data == null || data.length == 0){\r\n            alert(dataNullMsg);\r\n            $(''#graph'').html(\"\");\r\n            return;\r\n        }\r\n\r\n        var tempData;\r\n\r\n        options.series = new Array();\r\n        for(var i = 0; i < data.length; i++){\r\n            var yData = new Array();\r\n            options.series[i]=new Object();\r\n\r\n            tempData = data[i].seriesData;\r\n            for(var j = 0; j < tempData.length; j++){\r\n\r\n                var xValue = tempData[j][0];\r\n                if(xValue == 0){\r\n                    xData.push(zero);\r\n                }else if(xValue > 0 && xValue < 1){\r\n                    xData.push(xValue * 12 + month);\r\n                }else if(xValue >= 1){\r\n                    xData.push(xValue + year);\r\n                }else{\r\n                    xData.push(xValue);\r\n                }\r\n\r\n                var yValue;\r\n                if(xValue < 0.25){\r\n                    yValue = \"\";\r\n                }else{\r\n                    yValue = Number(tempData[j][1]);\r\n                }\r\n                if(xValue == 0.25 || xValue == 0.5 || xValue == 1 || xValue == 3\r\n                    || xValue == 5 || xValue == 7 || xValue == 10 || xValue == 30){\r\n                    yData.push({y:yValue,marker:{radius:2}});\r\n                }else{\r\n                    yData.push(yValue);\r\n                }\r\n                options.series[i].data = yData;\r\n                options.series[i].name = data[i].ycDefName;\r\n                options.series[i].color = colorArr[i];\r\n                options.series[i].dataGrouping = {enabled : false};\r\n                options.series[i].lineWidth = 1;\r\n            }\r\n\r\n        }\r\n\r\n        chart = new Highcharts.Chart(options);\r\n    }\r\n\r\n</script>\r\n</html>","headers":{"Date":"Sun, 18 Oct 2026 10:30:07 GMT","X-Frame-Options":"allowall","Vary":"Accept-Encoding","Expect-Ct":"enforce; max-age=86400","Strict-Transport-Security":"max-age=30; includeSubDomains;","X-Content-Type-Options":"nosniff","Content-Language":"und","Set-Cookie":"JSESSIONID=504D53737C916754E47354A41D205D78; Path=/cbweb-pbc-web; HttpOnly","Connection":"keep-alive","Content-Type":"text/html;charset=UTF-8","X-Xss-Protection":"1; mode=block"},"status_code":200,"$startTime":1792319406308,"$endTime":1792319407383}', 'reczz28OqCDpDaTY'),
