m\":\"长江干流\",\"stcd\":\"60112200\",\"stnm\":\"汉口\",\"tm\":1792404000000,\"wptn\":\"5\",\"z\":\"17.780\"},{\"q\":\"19400\",\"rvnm\":\"长江干流\",\"stcd\":\"60113400\",\"stnm\":\"九江\",\"tm\":1792404000000,\"wptn\":\"5\",\"z\":\"11.480\"},{\"q\":\"20900\",\"rvnm\":\"长江干流\",\"stcd\":\"60115000\",\"stnm\":\"大通\",\"tm\":1792404000000,\"wptn\":\"5\",\"z\":\"6.730\"},{\"q\":\"7440\",\"rvnm\":\"洞庭湖湖口\",\"stcd\":\"61512000\",\"stnm\":\"七里山\",\"tm\":1792404000000,\"wptn\":\"4\",\"z\":\"24.100\"},{\"q\":\"2200\",\"rvnm\":\"鄱阳湖\",\"stcd\":\"62601600\",\"stnm\":\"湖口\",\"tm\":1792404000000,\"wptn\":\"5\",\"z\":\"10.610\"},{\"rvnm\":\"长江\",\"stcd\":\"60107000\",\"stnm\":\"茅坪(二)\",\"tm\":1792404000000,\"wptn\":\"4\",\"z\":\"173.790\"},{\"oq\":\"10000\",\"rvnm\":\"长江干流\",\"stcd\":\"60106980\",\"stnm\":\"三峡水库\",\"tm\":1792404000000,\"wptn\":\"4\",\"z\":\"173.790\"},{\"rvnm\":\"汉江\",\"stcd\":\"61802500\",\"stnm\":\"龙王庙\",\"tm\":1792404000000,\"wptn\":\"4\",\"z\":\"166.370\"},{\"oq\":\"953\",\"q\":\"327\",\"rvnm\":\"汉江\",\"stcd\":\"61802700\",\"stnm\":\"丹江口水库\",\"tm\":1792404000000,\"wptn\":\"4\",\"z\":\"166.370\"}];\r\n\t\t\t\t\r\n\t\t\t\tvar sqHtml = \"<tr><td class=''tb1''><b>站名</b></td><td class=''tb1''><b>时间</b></td><td class=''tb1''><b>水位</b>(m)</td><td class=''tb1'' style=''padding-bottom: 3px;''><b>流量</b>(m<sup>3</sup>/s)</td></tr>\";\r\n\t\t\t\tfor(var i = 0; i < sssq.length; i++) {\r\n\t\t\t\t\tvar sssqTmp = sssq[i]\r\n\t\t\t\t\tvar trClass=\"\";\r\n\t\t\t\t\tif(i%2==0){\r\n\t\t\t\t\t\ttrClass=\"tb0\";\r\n\t\t\t\t\t}else{\r\n\t\t\t\t\t\ttrClass=\"tb1\";\r\n\t\t\t\t\t}\r\n\t\t\t\t\tvar z = \"-\";\r\n\t\t\t\t\tvar q = \"-\";\r\n\t\t\t\t\tvar oq = \"-\";\r\n\t\t\t\t\tvar wptnColor = \"\";\r\n\t\t\t\t\tif(sssqTmp.z) {\r\n\t\t\t\t\t\tz = (sssqTmp.z * 1).toFixed(2);\r\n\t\t\t\t\t}\r\n\t\t\t\t\tif(sssqTmp.q > 0) {\r\n\t\t\t\t\t\tq = (sssqTmp.q * 1).toFixed(0);\r\n\t\t\t\t\t}\r\n\t\t\t\t\tif(sssqTmp.oq > 0) {\r\n\t\t\t\t\t\toq = (sssqTmp.oq * 1).toFixed(0);\r\n\t\t\t\t\t}\r\n\t\t\t\t\tif(sssqTmp.wptn == 4) {\r\n\t\t\t\t\t\t// 落\r\n\t\t\t\t\t\twptnColor = ''#009900'';\r\n\t\t\t\t\t} else if(sssqTmp.wptn == 5) {\r\n\t\t\t\t\t\t// 涨\r\n\t\t\t\t\t\twptnColor = ''#ff0000'';\r\n\t\t\t\t\t}\r\n\t\t\t\t\tvar ioqTd = ''<td class=\"''+trClass+''\">'' + q + ''</td>'';\r\n\t\t\t\t\tif(oq != ''-'') {\r\n\t\t\t\t\t\tioqTd = ''<td class=\"''+trClass+''\">'' + q + ''(入)<br/>'' + oq + ''(出)'' + ''</td>'';\r\n\t\t\t\t\t}\r\n\t\t\t\t\t\r\n\t\t\t\t\tsqHtml += ''<tr><td class=\"''+trClass+''\"><a href=\"#''+sssqTmp.stcd+''\" >'' + sssqTmp.stnm + ''</a></td><td class=\"''+trClass+''\">'' + getTime(sssqTmp.tm) + ''</td><td class=\"''+trClass+''\"><font color=\"'' + wptnColor + ''\">'' + z + ''</font></td>'' + ioqTd + ''</tr>'';\r\n\r\n//sqHtml += ''<tr><td class=\"''+trClass+''\"><a href=\"#\" >'' + sssqTmp.stnm + ''</a></td><td class=\"''+trClass+''\">'' + sssqTmp.tm + ''</td><td class=\"''+trClass+''\"><font color=\"'' + wptnColor + ''\">'' + z + ''</font></td>'' + ioqTd + ''</tr>'';\r\n\t\t\t\t}\r\n$(\"#sssqold\").html(sqHtml);\r\n\t\t\t}\r\n\r\n\t\t\tfunction getTime(ntime) {\r\nif(ntime==''-''){return ''-'';}\r\n\t\t\t\tvar now = new Date(ntime);\r\n\t\t\t\tvar year = now.getYear();\r\n\t\t\t\tvar month = now.getMonth() + 1;\r\n\t\t\t\tvar date = now.getDate();\r\n\t\t\t\tvar hour = now.getHours();\r\n\t\t\t\tvar minute = now.getMinutes();\r\n\t\t\t\tvar second = now.getSeconds();\r\n\t\t\t\treturn PrefixInteger(date, 2) + \"日 \" + PrefixInteger(hour, 2) + \"时\"+PrefixInteger(minute, 2) + \"分\";;\r\n\r\n\t\t\t}\r\n\t\t\tfunction PrefixInteger(num, n) {\r\n\t\t\t\treturn(Array(n).join(0) + num).slice(-n);\r\n\t\t\t}\r\n\r\nwindow.addEventListener(''message'',function(rs){\r\n    var pointdata=rs.data;\r\nif(pointdata==''refresh''){\r\n     window.location.reload();\r\n}else{\r\nconsole.log(pointdata);\r\n}\r\n})\r\n</script>\r\n\t</body>\r\n\r\n</html>\r\n","headers":{"X-Bd-Remote-Connection-Info":"lf-lf02-bgp; bind=123.58.10.238; local=123.58.10.238:17320; remote=219.140.196.72:80","X-Bd-Upstream-Id":"lf-lf02-bgp","Connection":"Keep-Alive","Content-Type":"text/html;charset=utf-8","Date":"Mon, 19 Oct 2026 10:30:22 GMT","Server":"nginx","Set-Cookie":"WJSESSIONID=195BD26371AE1B90DED7884BFA354C17; Path=/; HttpOnly"}}', 'reczz28PEjJltUs2'),
