INSERT INTO cj_v1_announce_base (id, date, title, ann_type, summary, link, status, feishu_id) VALUES
(1, '2026-08-30T00:00:00.000+08:00', '长江电力2026年半年度报告', '定期报告', '营收379.29亿(+3.36%)；归母净利147.56亿(+13.02%)；六站发电量1327.44亿千瓦时(+4.81%)创同期新高；财务费用42.01亿(-13.61%)；三峡来水偏丰28.7%对冲金沙江偏枯', '[公司公告列表](https://vip.stock.finance.sina.com.cn/corp/go.php/vCB_AllBulletin/stockid/600900.phtml)', '已入模', 'recvtZ1HWnRYfI'),
(2, '2026-04-29T00:00:00.000+08:00', '长江电力2025年年度报告', '定期报告', '营收862.42亿(+2.07%)；归母净利345.03亿(+6.17%)；六站发电量3071.94亿千瓦时首破3000亿；每10股派10元，派息率70.92%；折旧195.29亿；财务费用93.71亿(-17.60亿)', '[2025年年度报告PDF](http://file.finance.sina.com.cn/211.154.219.97:9494/MRGG/CNSESH_STOCK/2026/2026-4/2026-04-30/12283277.PDF)', '已入模', 'recvtZ1HWntS45'),
(3, '2025-08-14T00:00:00.000+08:00', '未来五年(2026-2030年)股东分红回报规划', '分红', '每年现金分红不低于当年归母净利的70%，优先现金分红，写入公司章程', '[公告PDF](https://www.cypc.com.cn/eportal/attachDir/cypc/2025/09/2025090114575095227.pdf)', '已入模', 'recvtZ1HWneZwS'),
(4, '2025-01-07T00:00:00.000+08:00', '2024年发电量完成情况公告', '发电量', '六站全年2959.04亿千瓦时(+7.11%)；乌东德来水偏丰9.19%，三峡偏丰9.11%；Q4丰枯急转-17.60%', '[上交所公告PDF](https://static.sse.com.cn/disclosure/listedinfo/announcement/c/new/2025-01-08/600900_20250108_8R1Z.pdf)', '已入模', 'recvtZ1HWn7fpf'),
(5, '2026-08-25T00:00:00.000+08:00', '控股股东增持计划实施完毕', '重大事项', '三峡集团累计增持1.62亿股、金额44.99亿元，超过计划下限；治理信号，不改变任何模型输入', '[公司公告列表](https://vip.stock.finance.sina.com.cn/corp/go.php/vCB_AllBulletin/stockid/600900.phtml)', '无需入模', 'recvtZ1HWnA5yi'),
(6, '2026-07-08T00:00:00.000+08:00', '2026年度中期票据及超短期融资券发行', '融资', '中票票面利率2.05%/2.06%，超短融1.32%/1.34%，存量债务成本持续压降', '[公司公告列表](https://vip.stock.finance.sina.com.cn/corp/go.php/vCB_AllBulletin/stockid/600900.phtml)', '已入模', 'recvtZ1HWnJhVV');
INSERT INTO cj_v1_thesis_base (id, thesis, category, evidence, falsification, status, feishu_id) VALUES
(1, '资产永续且不可复制', '资产', '六站装机7179.5万千瓦全球最大；大坝按40-60年折旧，实际寿命以百年计；长江干流水电资源独占', '无（结构性事实）', '成立', 'recvtZ1IAXA78F'),
(2, '发电量长期围绕3000亿千瓦时中枢', '经营', '2023-2025年：2762.63/2959.04/3071.94亿千瓦时；六库联调节水增发140.1亿千瓦时', '连续两年低于2700亿千瓦时（气候或调度格局变化）', '成立', 'recvtZ1IAXjIUr'),
(3, '电价长期稳定', '经营', '综合电价2023-2025年：0.2827/0.2856/0.2807元；市场化占比约37.76%，多省消纳分散风险', '综合电价年降幅超过3%', '成立', 'recvtZ1IAXYOKS'),
(4, '成本退坡驱动净利中枢上移', '财务', '财务费用2023-2025年：125.56/111.31/93.71亿；三峡机组折旧2026年起批量到期；新发债利率1.32%-2.06%', '财务费用止降回升且折旧不再下降（利率上行+新增大额负债）', '成立', 'recvtZ1IAXvVim'),
(5, '分红承诺可信且可持续', '治理', '2021-2025年派息率70.6%-94.3%；2026-2030年新承诺≥70%并写入公司章程', '派息率低于70%或以股票股利替代现金', '成立', 'recvtZ1IAXi13Q'),
(6, '资本配置保持纪律', '治理', '抽蓄容量电价按资本金内部收益率6.5%核定；在建及推进约800万千瓦、2028年起投产', '大额低回报并购或增持（投入资本回报低于折现率）', '观察', 'recvtZ1IAXLHDA'),
(7, '利率是最大估值风险', '风险', 'r=10年期国债+3.5%；当前10年期国债1.69%处历史低位，利率上行将重伤类债资产估值', '不适用（风险描述，触发时下调估值而非论点本身）', '成立', 'recvtZ1IAXpsGv');
